window.EXP_PROSE = {
"titration":{"apparatus":["碱式滴定管","酸式滴定管","锥形瓶","铁架台","滴定管夹","洗瓶"],"observation":"接近终点时，滴入处出现局部粉红色并迅速消失；终点时整体呈浅粉红色并保持半分钟以上。","conclusion":"平行测定三次，相对偏差应小于 0.2%。读数必须读到小数点后两位（0.01 mL），且视线与凹液面最低处相平。","cautions":["酸式滴定管不能装碱性溶液，碱式滴定管不能装酸性或氧化性溶液。","锥形瓶不能润洗，否则待测物偏多导致结果偏高。","滴定速度先快后慢，接近终点时逐滴甚至半滴加入。","读数时俯视或仰视都会带来系统误差。"]},
"flame-test":{"apparatus":["铂丝（或洁净铁丝）","酒精灯","蓝色钴玻璃","表面皿"],"observation":"钠——黄色；钾——紫色（透过钴玻璃）；钙——砖红色；铜——绿色；钡——黄绿色。","conclusion":"焰色反应是元素的物理性质，可用于金属元素的初步鉴定；但只能作为辅助手段，需结合其他检验方法确认。","cautions":["铂丝昂贵，也可用洁净铁丝代替，但铁丝本身有颜色干扰。","必须用盐酸清洗铂丝，因为金属氯化物易挥发，灼烧后不残留。","酒精灯外焰温度最高，焰色观察最明显。","钾盐中常混有微量钠，不透过钴玻璃会只看到黄色。"]},
"electrolysis-water":{"apparatus":["电解水装置（霍夫曼电解器）","直流电源","导线","带火星木条"],"observation":"两极均有气泡产生，阴极气泡更快；阴极气体体积约为阳极的 2 倍；阴极气体可燃，阳极气体助燃。","conclusion":"水由氢、氧两种元素组成，化学式 H₂O；电解水是将电能转化为化学能的过程。","cautions":["纯水几乎不导电，必须加入电解质。","氢气收集后应先验纯再点燃，防止爆鸣。","电压不宜过高，避免剧烈放热。","加入氢氧化钠时注意腐蚀性。"]},
"iodine-clock":{"apparatus":["烧杯","量筒","玻璃棒","秒表"],"observation":"混合初期溶液无色，静置一段可预测的时间后，突然整杯变为深蓝色。","conclusion":"蓝色出现的延迟时间与亚硫酸氢钠浓度成反比，这是典型的动力学控制“时钟反应”。","cautions":["碘酸钾是强氧化剂，避免与可燃物、还原剂混放。","稀硫酸有腐蚀性，操作时戴护目镜。","反应液不宜久置，实验后稀释处理。","变色瞬间不要惊慌，属于正常现象。"]},
"elephant-toothpaste":{"apparatus":["量筒或锥形瓶","托盘","护目镜","手套"],"observation":"瞬间产生大量致密泡沫，从容器中连续涌出，容器明显发热。","conclusion":"碘化钾降低了过氧化氢分解的活化能，是催化剂；反应放热使泡沫体积迅速膨胀。","cautions":["30% 过氧化氢有强腐蚀性，接触皮肤会造成白斑灼伤，必须戴手套和护目镜。","反应剧烈放热，不要使用密闭容器。","泡沫可能带出腐蚀性液体，注意保护眼睛和衣物。","仅限教师演示，学生不要自行配制高浓度过氧化氢。"]},
"blue-bottle":{"apparatus":["锥形瓶或透明瓶","橡胶塞","量筒"],"observation":"蓝色 ↔ 无色反复切换，可循环十余次；瓶内液面上方空气越多，变蓝越明显。","conclusion":"亚甲基蓝的氧化还原是可逆的：振荡使氧气溶入将还原态氧化为蓝色，静置时葡萄糖又把氧化态还原为无色。","cautions":["氢氧化钠有腐蚀性，避免接触皮肤和眼睛。","瓶塞要塞紧，但不要剧烈摇晃玻璃瓶。","实验后废液交实验员统一处理，不要直接倒入下水道。"]},
"silver-mirror":{"apparatus":["洁净试管","水浴锅","胶头滴管","试管夹"],"observation":"试管内壁逐渐出现银白色金属光泽，最终形成光亮的银镜；溶液中有少量黑色银粒。","conclusion":"醛基具有还原性，能被弱氧化剂托伦试剂氧化，同时把银离子还原为单质银。","cautions":["托伦试剂必须现配现用，久置生成雷爆银，受摩擦或受热会爆炸。","试管必须洁净，否则银镜不亮、呈黑色斑点。","水浴加热，不要用明火直接加热试管。","实验后的含银残液统一回收，由实验员当日处理，严禁倒入下水道或久置。"]},
"thermite":{"apparatus":["纸漏斗（内衬氧化铝）","铁架台","坩埚","沙盘","长柄点火器"],"observation":"强光、大量白烟、剧烈放热，纸漏斗被烧穿，铁水呈亮红色落入沙中，冷却后为铁珠。","conclusion":"铝的还原性强于铁，在高温下把铁从其氧化物中置换出来；铝热反应可用于焊接钢轨和冶炼难熔金属。","cautions":["极高危实验：反应瞬间温度超过 2000 ℃，火花四溅，仅限室外或专用实验室由教师操作。","周围不得有可燃物、易燃气体；不得有水，遇水会剧烈汽化喷溅。","铝粉粉尘与空气混合有爆炸风险，取用时要轻、要远离火源。","旁观者必须保持 5 米以上距离并佩戴护目镜。严禁自行尝试。"]},
"sodium-water":{"apparatus":["烧杯","镊子","滤纸","小刀","玻璃片"],"observation":"钠浮在水面（密度小于水）、熔成小球（反应放热、熔点低）、四处游动（氢气推动）、发出嘶嘶响声，溶液变红（生成 NaOH）。","conclusion":"钠是活泼金属，与水剧烈反应生成氢氧化钠和氢气；现象可概括为“浮、熔、游、响、红”。","cautions":["钠必须保存在煤油中，隔绝空气和水汽。","取用钠不能用手，切下的钠块必须放回煤油，严禁丢入水槽或垃圾桶。","用量必须很小（绿豆大小），量大会剧烈燃烧甚至爆炸。","反应可能引燃氢气，烧杯要盖玻璃片，操作时戴护目镜。"]},
"iron-burning":{"apparatus":["集气瓶","坩埚钳","酒精灯"],"observation":"铁丝剧烈燃烧、火星四射，放出大量热，生成黑色固体（Fe₃O₄）。","conclusion":"铁在纯氧中燃烧生成四氧化三铁；瓶底的沙或水用于防止高温熔融物炸裂瓶底。","cautions":["瓶底必须留水或细沙，否则高温熔融物会使瓶底炸裂。","铁丝不要接触瓶壁，以免局部过热。","火柴快燃尽时再伸入，避免消耗过多氧气。"]},
"paper-chromatography":{"apparatus":["大试管或层析缸","毛细管","镊子","直尺"],"observation":"黑色墨水分离出蓝、红、黄等色带；叶绿体色素分离出胡萝卜素、叶黄素、叶绿素 a、叶绿素 b 四条色带。","conclusion":"不同色素在滤纸上的吸附能力与在展开剂中的溶解度不同，因此移动速率不同，实现分离。","cautions":["样点不能浸入展开剂，否则色素会直接溶解在展开剂中。","点样要小而集中，斑点过大会导致色带重叠。","展开剂多为有机溶剂，操作时注意通风。","取滤纸时只接触边缘，避免手上油脂污染。"]},
"starch-iodine":{"apparatus":["试管","酒精灯","烧杯","胶头滴管"],"observation":"滴入碘液立即变深蓝色；加热后蓝色褪去；冷却后蓝色重新出现。","conclusion":"淀粉与碘的显色是物理包合作用，具有可逆性，可用于检验淀粉或碘的存在。","cautions":["碘液有腐蚀性，避免入口和接触眼睛。","淀粉溶液现配现用，久置会变质。","加热时注意试管口不要对着人。"]},
"protein-denaturation":{"apparatus":["试管","试管架","酒精灯","胶头滴管"],"observation":"加热后蛋清凝固变白；硫酸铜、乙醇、强酸强碱均使蛋白质产生沉淀或凝固；加水后不再溶解。","conclusion":"蛋白质变性是空间结构被破坏的过程，不可逆；重金属盐使人中毒正是因为使体内蛋白质变性。","cautions":["浓盐酸和氢氧化钠有强腐蚀性，操作时戴护目镜和手套。","硫酸铜有毒，废液需回收处理。","加热试管时管口不要对着人。"]},
"extraction":{"apparatus":["分液漏斗","铁架台","烧杯","玻璃棒"],"observation":"振荡后下层四氯化碳变为紫红色，上层水层颜色明显变浅；静置后界面清晰。","conclusion":"碘被萃取到四氯化碳中，说明碘在有机溶剂中的溶解度更大；分液可实现两相分离。","cautions":["四氯化碳有毒且致癌，必须在通风橱内操作，避免吸入蒸气。","振荡时必须不断放气，否则漏斗内压强过大会冲开塞子。","上层液体必须从上口倒出，不能从下口放出，以免污染。","含卤代烃废液单独收集，不得倒入下水道。"]},
"distillation":{"apparatus":["蒸馏烧瓶","温度计","冷凝管","接收瓶","酒精灯","铁架台"],"observation":"温度升至约 78 ℃ 后保持稳定，馏出液澄清；剩余液体温度继续升高。","conclusion":"蒸馏可以分离沸点相差较大的互溶液体；温度计位置和冷凝水方向是实验成败的关键。","cautions":["不能蒸干，烧瓶内液体快尽时停止加热。","必须加沸石，否则可能暴沸冲出。","乙醇易燃，实验区域禁止明火以外的火源，接收瓶不要敞口太久。","冷凝水必须先通后停。"]},
"galvanic-cell":{"apparatus":["烧杯","导线","电流表","直流电源","鳄鱼夹"],"observation":"原电池中电流表指针偏转，铜片表面产生气泡；电镀后铁片表面覆盖一层红色铜。","conclusion":"原电池把化学能转化为电能；电解池把电能转化为化学能。电镀时镀件作阴极，镀层金属作阳极。","cautions":["稀硫酸有腐蚀性，操作时戴护目镜。","电镀液含重金属离子，废液必须回收，不得排放。","电镀电流不宜过大，否则镀层粗糙。","实验结束后及时断开电源。"]},
"recrystallization":{"apparatus":["烧杯","玻璃棒","加热套","漏斗","抽滤装置","表面皿"],"observation":"热水中完全溶解为无色溶液；冷却后析出白色针状晶体；活性炭使溶液脱色。","conclusion":"重结晶适用于溶解度随温度变化较大的固体物质；趁热过滤和缓慢冷却是提高纯度的关键。","cautions":["趁热过滤动作要快，否则晶体在漏斗中提前析出堵塞。","活性炭易燃，不要靠近明火，用完密封保存。","不要用冷水突然冷却热溶液，以免晶体过细夹带杂质。","抽滤时先开泵再倒液，结束时先拔管再关泵。"]},
"heat-neutralization":{"apparatus":["保温杯（或量热计）","温度计","量筒","环形玻璃搅拌棒","烧杯"],"observation":"混合后温度迅速上升，约 1–2 分钟达到最高点，随后缓慢下降；对照组的温升明显更小。","conclusion":"强酸与强碱的稀溶液中和热约为 −57.3 kJ/mol。测定值通常偏小，主要因为量热计向环境散热、盖口蒸发和搅拌带入热量。","cautions":["盐酸和氢氧化钠都有腐蚀性，必须戴护目镜，避免溅到皮肤和眼睛。","温度计要轻拿轻放，不能当搅拌棒用。","碱液要一次快速倒入并立即盖盖，减少散热。","废液交实验员按危险废物处理，不要自行中和、稀释或排放。"]},
"salt-purification":{"apparatus":["烧杯","玻璃棒","漏斗","滤纸","蒸发皿","酒精灯","铁架台","托盘天平"],"observation":"滤纸上残留棕黄色泥沙；滤液无色透明；蒸发后期出现白色晶体，母液明显减少。","conclusion":"过滤只能除去不溶性杂质，可溶性杂质仍可能少量残留，所以产品纯度有限。产率低于 100%，常见原因是溶解不充分、过滤转移损失和蒸发飞溅。","cautions":["加热蒸发皿要用坩埚钳夹取，不能直接用手拿。","蒸发时玻璃棒持续搅拌，防止局部过热造成液滴飞溅。","滤纸边缘要低于漏斗口，液面要低于滤纸边缘，否则滤液会从缝隙流下。","母液不要直接倒掉，按老师要求回收或处理。"]},
"solution-prep":{"apparatus":["分析天平","100 mL 容量瓶","烧杯","玻璃棒","胶头滴管","量筒","洗瓶"],"observation":"溶液无色澄清；定容时液面接近刻度线，滴管加入的速度要慢，视线与刻度线相平。","conclusion":"俯视刻度线会使体积偏小、浓度偏高；仰视则体积偏大、浓度偏低。未洗涤烧杯或未冷却就转移，都会带来误差。","cautions":["容量瓶不能加热，也不能用来长期存放溶液。","定容后不要再加水，否则浓度偏低；也不要把溶液倒回容量瓶“补正”。","托盘天平只能称到 0.1 g，配不出准确的 0.100 mol/L，需要分析天平。","易水解的盐（如氯化铁）配制时先加少量相应的酸抑制水解。"]},
"ion-tests":{"apparatus":["试管","试管架","胶头滴管","导管","烧杯"],"observation":"AgCl 和 BaSO₄ 都是白色沉淀；碳酸盐加酸产生气泡并使石灰水变浑浊；硫氰化铁溶液呈血红色。","conclusion":"检验离子要选特征反应，并先用试剂排除同类干扰：检验 SO₄²⁻ 先用盐酸排除 CO₃²⁻ 和 SO₃²⁻，检验 Cl⁻ 用稀硝酸排除 CO₃²⁻。","cautions":["硝酸银见光易分解，应装在棕色瓶里，避免沾到皮肤和衣物。","氯化钡有毒，废液要回收，不能直接倒入水槽。","硫氰化钾遇酸可能产生有毒气体，废液集中处理。","胶头滴管不能伸入试管内，也不要交叉使用。"]},
"fe-steam":{"apparatus":["硬质玻璃管","酒精喷灯","铁架台","单孔塞","导管","蒸发皿","火柴"],"observation":"肥皂泡点燃时发出爆鸣声，或产生淡蓝色火焰；管内固体仍为黑色，但有磁性。","conclusion":"高温下铁与水蒸气反应生成四氧化三铁和氢气。点燃前必须验纯，尖锐的爆鸣声说明氢气不纯。","cautions":["玻璃管高温，取放要用坩埚钳，防止烫伤和骤冷炸裂。","点燃前必须检验氢气纯度，否则可能发生爆鸣甚至爆炸。","结束时先撤导管再停止加热，防止肥皂液倒吸。","铁粉易燃，远离火源，少量取用。"]},
"al-naoh":{"apparatus":["试管","试管夹","酒精灯","导管","水槽","火柴"],"observation":"铝片表面气泡密集，溶液温度升高；点燃收集的气体产生淡蓝色火焰。","conclusion":"铝既能与强酸反应，也能与强碱反应，是两性金属；反应中铝作还原剂，水作氧化剂。","cautions":["氢氧化钠有强腐蚀性，必须戴护目镜和手套，避免溅到皮肤。","氢气必须验纯后再点燃，否则会爆鸣。","该反应放热明显，试管口不要对着人。","偏铝酸钠废液要回收处理。"]},
"aloh3-amphoteric":{"apparatus":["试管","胶头滴管","试管架"],"observation":"两支试管中的白色胶状沉淀都逐渐溶解，形成澄清溶液。","conclusion":"氢氧化铝既能与酸反应又能与强碱反应，是两性氢氧化物。制备时用氨水而不用氢氧化钠，因为氢氧化钠过量会把沉淀溶解。","cautions":["氨水有刺激性气味，操作要在通风处进行。","氢氧化钠和盐酸都有腐蚀性，避免溅到皮肤和眼睛。","氢氧化铝胶状沉淀容易吸附杂质，洗涤时动作要轻。","废液交实验员按危险废物处理，不要自行中和、稀释或排放。"]},
"ammonia-fountain":{"apparatus":["圆底烧瓶","双孔橡皮塞","尖嘴玻璃管","胶头滴管","止水夹","烧杯","铁架台"],"observation":"水迅速沿导管上升，从尖嘴喷出形成喷泉；进入瓶内的水立即变为红色。","conclusion":"氨气极易溶于水，使瓶内气体压强急剧减小，外界大气压把水压入瓶内；氨水显碱性，使酚酞变红。","cautions":["氨气有强烈刺激性，制取和收集必须在通风橱内进行。","装置必须干燥、气密性良好，否则喷泉效果差。","烧瓶内氨气要充满，否则压强差不够。","实验结束先打开止水夹泄压，再拆卸装置，防止倒吸。"]},
"hcl-nh3-smoke":{"apparatus":["玻璃棒","表面皿","通风橱"],"observation":"两根玻璃棒靠近时，空气中出现大量白色烟状固体小颗粒。","conclusion":"氨气与氯化氢气体反应生成氯化铵固体小颗粒，所以看到的是“白烟”而不是“白雾”。","cautions":["浓盐酸和浓氨水挥发出的气体都有强烈刺激性，必须在通风橱内操作。","两种试剂用量要少，玻璃棒不要接触，避免大量放热。","不要正对瓶口闻气味，应用手轻轻扇动。","实验后及时洗手，废液倒入废液缸。"]},
"h2-combustion":{"apparatus":["简易气体发生装置","试管","水槽","导管","烧杯","火柴"],"observation":"纯净氢气燃烧发出淡蓝色火焰；干冷烧杯内壁出现水雾。","conclusion":"氢气燃烧生成水；点燃前必须验纯，爆鸣声越尖锐，混入的空气越多。","cautions":["不纯的氢气点燃可能爆炸，必须验纯后再点燃。","点燃时导管口要远离可燃物，人不要正对管口。","用锌与稀硫酸制氢时，装置不能密闭，防止压强过大。","实验结束先撤导管再停止反应。"]},
"ethanol-oxidation":{"apparatus":["酒精灯","坩埚钳","试管","试管夹"],"observation":"铜丝灼烧后变黑，插入乙醇后由黑变红；反复几次后试管内液体有刺激性气味。","conclusion":"铜在反应中先被氧化为氧化铜，再被乙醇还原为铜，起催化剂作用；乙醇被氧化为乙醛。","cautions":["乙醇易燃，试管口不要对着人，远离明火。","乙醛有刺激性气味，不要直接闻，用手扇闻。","铜丝灼烧后温度很高，取放要用坩埚钳。","实验在通风处进行，废液回收。"]},
"glucose-fehlings":{"apparatus":["试管","试管夹","酒精灯","胶头滴管","烧杯"],"observation":"加热后蓝色悬浊液先变黄绿色，随后出现砖红色沉淀。","conclusion":"葡萄糖分子中含有醛基，具有还原性，能把氢氧化铜还原为氧化亚铜。","cautions":["氢氧化钠有腐蚀性，避免溅到皮肤和眼睛。","氢氧化铜必须现配现用，放置过久会失效。","加热要均匀，试管口不要对着人。","砖红色沉淀不要随意丢弃，按废液处理。"]},
"sucrose-hydrolysis":{"apparatus":["试管","试管夹","酒精灯","水浴","胶头滴管"],"observation":"第一支试管无砖红色沉淀；第二支试管加热后出现砖红色沉淀。","conclusion":"蔗糖是非还原糖，在酸催化下水解生成葡萄糖和果糖，二者都是还原糖。检验前必须先中和硫酸，否则氢氧化铜会被酸溶解。","cautions":["稀硫酸有腐蚀性，避免溅到皮肤和眼睛。","水浴加热比直接加热更均匀安全。","中和酸时要逐滴加入并振荡，避免碱过量太多。","实验后废液集中处理。"]},
"protein-salting":{"apparatus":["试管","胶头滴管","酒精灯","试管夹"],"observation":"第一支出现白色沉淀，加水后沉淀消失；第二支加热后出现白色凝固物，加水不再溶解。","conclusion":"盐析是可逆的物理过程，蛋白质结构未破坏；加热使蛋白质变性，结构被破坏，不可逆。","cautions":["鸡蛋清要新鲜配制，避免变质产生异味。","加热时试管口不要对着人，防止液体喷出。","硫酸铵废液按实验室要求回收，重金属盐废液必须交危废。","不要用嘴接触实验药品。"]},
"ester-hydrolysis":{"apparatus":["试管","试管夹","水浴","胶头滴管"],"observation":"氢氧化钠溶液中的酯层最先消失，稀硫酸中较慢，纯水中最慢；加热后酯的香味减弱。","conclusion":"酯的水解是可逆反应，酸作催化剂；在碱性条件下生成的酸被中和，平衡正向移动，水解趋于完全。","cautions":["乙酸乙酯易燃、有香味，但不能用嘴吸，闻气味要扇闻。","水浴温度不宜过高，防止乙酸乙酯大量挥发。","氢氧化钠和稀硫酸都有腐蚀性，注意防护。","实验后废液交实验员统一处理，不要自行中和。"]},
"electrolysis-brine":{"apparatus":["U 形管","石墨电极","铁电极","12 V 直流电源","导线","试管"],"observation":"阳极产生黄绿色刺激性气体，试纸变蓝；阴极产生无色气体，附近溶液变红；点燃阴极气体有爆鸣声或淡蓝色火焰。","conclusion":"电解饱和食盐水生成氢氧化钠、氢气和氯气：阳极氯离子放电，阴极水得电子。","cautions":["氯气有毒，实验要在通风橱内进行，用量要少。","必须用直流电，不能用交流电。","石墨电极容易碎裂，插入时动作要轻。","电解后的废液含碱和氯，须交实验员按危废处理，不能直接排放。"]},
"sacrificial-anode":{"apparatus":["培养皿","烧杯","酒精灯","导线","砂纸"],"observation":"铜片附近的凝胶出现蓝色和红色斑块；锌片附近的铁钉周围几乎没有变化。","conclusion":"与锌接触时铁作正极被保护，锌作负极被腐蚀，这就是牺牲阳极的阴极保护法；与铜接触时铁作负极，加速腐蚀。","cautions":["铁氰化钾有毒，避免接触皮肤和误食，废凝胶要回收。","热琼脂温度高，倒盘时要小心烫伤。","金属表面要打磨干净，否则现象不明显。","实验后洗手，废液按有毒废液处理。"]},
"pbi2-equilibrium":{"apparatus":["试管","试管夹","酒精灯","烧杯","胶头滴管"],"observation":"混合时生成黄色沉淀；加热后沉淀溶解成无色或浅黄色溶液；冷却后析出金黄色闪亮晶体。","conclusion":"沉淀溶解平衡是动态平衡，温度改变使溶解度改变，平衡发生移动；碘化铅的溶解度随温度升高而增大。","cautions":["铅盐有毒，必须戴手套，严禁入口，废液回收。","加热时试管口不要对着人，防止暴沸。","冷却析晶时不要剧烈摇动，否则晶体细小。","实验后彻底洗手。"]},
"cuammine":{"apparatus":["试管","胶头滴管","烧杯"],"observation":"先出现蓝色絮状沉淀，氨水过量后沉淀消失，溶液呈深蓝色；加乙醇后析出深蓝色晶体。","conclusion":"氨分子与铜离子形成配位键，生成四氨合铜离子；乙醇降低配合物溶解度使其结晶析出。","cautions":["氨水有刺激性，操作在通风处进行。","硫酸铜有毒，避免入口和接触伤口。","乙醇易燃，远离明火。","废液中的铜离子要回收处理。"]},
"kmno4-h2o2":{"apparatus":["酸式滴定管","锥形瓶","移液管","铁架台","洗瓶"],"observation":"滴定过程中紫红色迅速褪去并产生气泡；终点时溶液呈浅粉红色并保持半分钟。","conclusion":"高锰酸钾在酸性条件下氧化双氧水，自身被还原为无色锰离子；不能用盐酸酸化，因为氯离子也会被氧化。","cautions":["高锰酸钾是强氧化剂，避免与可燃物、还原性物质接触。","硫酸有腐蚀性，稀释时要把酸加入水中。","高锰酸钾溶液见光易分解，应现配现用或保存在棕色瓶中。","必须使用酸式滴定管，不能用碱式滴定管。"]},
"fruit-battery":{"apparatus":["锌片","铜片","导线","电压表","发光二极管","砂纸"],"observation":"电压表指针偏转，读数约 0.5–1 V；多个水果电池串联后可使发光二极管微亮。","conclusion":"水果中的酸性电解质与两种活泼性不同的金属构成原电池，把化学能转化为电能。","cautions":["金属片要打磨干净，否则表面氧化膜会增大内阻。","不要用市电或充电器做实验，只用低压电表和小灯泡。","水果和金属片实验后不要食用水果。","发光二极管注意正负极，长脚接正极。"]},
"hydrogen-burn":{"apparatus":["启普发生器","尖嘴导管","火柴","干燥烧杯"],"observation":"火焰呈淡蓝色；烧杯内壁出现水雾，无水硫酸铜变蓝。","conclusion":"氢气燃烧生成水，产物检验证明含氢元素和氧元素。","cautions":["点燃前必须验纯，否则可能爆炸。","氢气易燃，实验区禁止明火。"]},
"co2-extinguish":{"apparatus":["集气瓶","导管","烧杯","阶梯蜡烛"],"observation":"下层蜡烛先熄灭，上层后熄灭。","conclusion":"二氧化碳密度大于空气且不支持燃烧，可用于灭火。","cautions":["二氧化碳浓度过高会窒息，注意通风。","蜡烛倾倒注意防火。"]},
"oxygen-glow":{"apparatus":["试管","导管","集气瓶","水槽"],"observation":"带火星木条复燃，燃烧更旺。","conclusion":"氧气具有助燃性，可用于检验氧气。","cautions":["试管口略向下倾斜，防止冷凝水倒流。","实验结束先撤导管再熄灯。"]},
"so2-bleach":{"apparatus":["试管","导管","酒精灯","通风橱"],"observation":"品红溶液褪色；加热后红色恢复。","conclusion":"二氧化硫的漂白是可逆的，与氯水漂白不同。","cautions":["二氧化硫有毒，操作在通风橱中进行并吸收尾气。","加热试管时管口不对人。"]},
"chlorine-bleach":{"apparatus":["试管","滴管","通风橱"],"observation":"布条褪色；石蕊试纸先变红后褪色。","conclusion":"氯水中的次氯酸具有漂白性，漂白不可逆。","cautions":["氯水有刺激性，操作通风。","氯水现配现用，避免失效。"]},
"no2-dimer":{"apparatus":["圆底烧瓶","导管","热水","冰水","通风橱"],"observation":"热水中颜色加深，冰水中颜色变浅。","conclusion":"温度改变使平衡移动；NO₂ 红棕色，N₂O₄ 无色。","cautions":["二氧化氮有毒，操作在通风橱中进行。","气体密封，防止泄漏。"]},
"h2s-precip":{"apparatus":["启普发生器","导管","试管","通风橱"],"observation":"生成黑色沉淀。","conclusion":"硫化氢具有还原性和酸性，可与重金属盐生成难溶硫化物。","cautions":["硫化氢剧毒，必须在通风橱中操作。","尾气必须吸收，严禁直接排放。"]},
"co-reduction":{"apparatus":["硬质玻璃管","酒精灯","导管","尾气处理装置","通风橱"],"observation":"黑色氧化铜变为红色，澄清石灰水变浑浊。","conclusion":"一氧化碳具有还原性，可还原金属氧化物。","cautions":["一氧化碳剧毒，必须通风并处理尾气。","先通气后加热，防止爆炸。"]},
"carbonate-test":{"apparatus":["试管","导管","胶头滴管"],"observation":"产生气泡，石灰水变浑浊。","conclusion":"碳酸根离子可用加酸产生二氧化碳的方法检验。","cautions":["盐酸具有腐蚀性。","导管口不要伸入石灰水过深，防止倒吸。"]},
"sulfate-test":{"apparatus":["试管","滴管"],"observation":"生成白色沉淀，不溶于稀盐酸。","conclusion":"硫酸根离子可用酸化后加钡盐的方法检验。","cautions":["可溶性钡盐有毒，废液集中处理。","必须先用盐酸排除碳酸根干扰。"]},
"chloride-test":{"apparatus":["试管","滴管"],"observation":"生成白色沉淀，不溶于稀硝酸。","conclusion":"氯离子可用硝酸银溶液检验，需酸化排除干扰。","cautions":["硝酸银腐蚀皮肤并染色。","沉淀见光分解，观察后避光处理。"]},
"ammonium-test":{"apparatus":["试管","酒精灯","镊子","玻璃棒"],"observation":"产生刺激性气味气体，试纸变蓝。","conclusion":"铵根离子可用加碱加热产生氨气的方法检验。","cautions":["氨气有刺激性，操作通风。","加热时管口不对人。"]},
"fe3-scn":{"apparatus":["试管","滴管"],"observation":"溶液变为血红色。","conclusion":"硫氰化钾可用于检验铁离子，灵敏度高。","cautions":["硫氰化钾有毒，避免误食。","废液集中处理。"]},
"fe2-fe3":{"apparatus":["试管","滴管"],"observation":"亚铁溶液加硫氰化钾不变红；加氯水后变红；加铁粉后红色褪去。","conclusion":"亚铁离子可被氧化为铁离子，铁离子可被铁还原为亚铁离子。","cautions":["氯水有刺激性，操作通风。","亚铁溶液现配现用。"]},
"halogen-displacement":{"apparatus":["试管","滴管","通风橱"],"observation":"溴化钠体系有机层呈橙红色；碘化钾体系呈紫红色。","conclusion":"氯的氧化性强于溴和碘，可置换出溴和碘。","cautions":["氯水、溴、碘均有毒性和腐蚀性，操作通风并戴手套。","四氯化碳有毒，避免吸入。"]},
"metal-activity":{"apparatus":["试管","镊子"],"observation":"锌产生气泡最快，铁较慢，铜无现象；锌、铁表面析出红色铜。","conclusion":"金属活动性顺序中靠前的金属能置换出酸中的氢和较不活泼金属。","cautions":["氢气易燃，远离火源。","硫酸铜溶液有刺激性。"]},
"nahco3-thermal":{"apparatus":["套管装置","酒精灯","导管","试管"],"observation":"碳酸氢钠一侧石灰水变浑浊，碳酸钠一侧无明显变化。","conclusion":"碳酸氢钠热稳定性差，受热分解；碳酸钠稳定。","cautions":["加热时防止倒吸。","实验结束先撤导管再熄灯。"]},
"kmno4-thermal":{"apparatus":["试管","酒精灯","带火星木条"],"observation":"紫色晶体变为黑色，木条复燃。","conclusion":"高锰酸钾受热分解产生氧气，可用于实验室制氧。","cautions":["高锰酸钾强氧化性，避免与有机物接触。","加热时管口略向下倾斜。"]},
"na2o2-water":{"apparatus":["试管","带火星木条","滴管"],"observation":"剧烈反应并放出气体，木条复燃；溶液使酚酞变红后褪色。","conclusion":"过氧化钠与水反应生成氧气和氢氧化钠，具有强氧化性。","cautions":["过氧化钠强氧化性，避免接触皮肤和可燃物。","反应放热剧烈，少量取用。"]},
"na2o2-co2":{"apparatus":["干燥管","导管","集气瓶","带火星木条"],"observation":"木条复燃。","conclusion":"过氧化钠可用于呼吸面具和潜水艇中供氧。","cautions":["过氧化钠强氧化性，装置要干燥。","二氧化碳过量时注意尾气。"]},
"al-oxide-film":{"apparatus":["试管","镊子","砂纸"],"observation":"未打磨铝片反应很慢；打磨后表面迅速析出红色铜。","conclusion":"铝表面致密氧化膜具有保护作用。","cautions":["氯化汞剧毒，本实验尽量不使用。","硫酸铜溶液有刺激性。"]},
"electrolysis-cuso4":{"apparatus":["电解槽","直流电源","导线","试管"],"observation":"阴极析出红色铜，阳极产生气泡，溶液蓝色变浅。","conclusion":"电解硫酸铜溶液时阴极析铜、阳极放氧，总反应生成铜、氧气和硫酸。","cautions":["电解时电压不宜过高。","硫酸铜溶液有刺激性，避免接触皮肤。"]},
"electroplating-copper":{"apparatus":["电解槽","直流电源","导线"],"observation":"铁片表面覆盖一层红色铜。","conclusion":"电镀时阳极金属溶解、阴极析出，镀层均匀致密。","cautions":["电镀废液含铜离子，集中回收。","通电时避免短路。"]},
"fuel-cell":{"apparatus":["燃料电池演示器","小风扇","导线"],"observation":"风扇转动，说明化学能转化为电能。","conclusion":"燃料电池将燃料的化学能直接转化为电能，能量利用率高。","cautions":["氢气易燃，验纯后使用。","避免氢气与空气混合。"]},
"corrosion-oxygen":{"apparatus":["培养皿","导管","试管"],"observation":"铁钉附近出现蓝色，周围琼脂变红，液面上升。","conclusion":"铁在中性溶液中发生吸氧腐蚀，消耗氧气。","cautions":["铁氰化钾有毒，避免接触。","实验后洗手。"]},
"corrosion-acid":{"apparatus":["试管","导管"],"observation":"铁钉表面产生气泡，溶液逐渐变浅绿色。","conclusion":"铁在酸性条件下发生析氢腐蚀。","cautions":["氢气易燃，远离火源。","盐酸具有腐蚀性。"]},
"electrolysis-ki":{"apparatus":["电解槽","直流电源","导线"],"observation":"阳极附近溶液变蓝，阴极产生气泡。","conclusion":"碘离子在阳极被氧化为碘，水在阴极被还原为氢气。","cautions":["碘蒸气有刺激性，注意通风。","电压不宜过高。"]},
"filtration":{"apparatus":["漏斗","滤纸","烧杯","玻璃棒","铁架台"],"observation":"滤纸上留下白色固体，滤液澄清。","conclusion":"过滤适用于分离不溶性固体和液体，遵循一贴二低三靠。","cautions":["玻璃棒引流时不要戳破滤纸。","漏斗下端要靠在烧杯内壁，防止溅出。"]},
"evaporation":{"apparatus":["蒸发皿","酒精灯","玻璃棒","坩埚钳"],"observation":"水分逐渐减少，析出白色晶体。","conclusion":"蒸发结晶适用于溶解度受温度影响较小的溶质。","cautions":["加热时用玻璃棒搅拌，防止局部过热飞溅。","不可蒸干后再强热，防止固体分解。"]},
"decantation":{"apparatus":["烧杯","玻璃棒"],"observation":"上层液澄清，沉淀留在杯底。","conclusion":"倾析适用于沉淀颗粒较大、易沉降的体系。","cautions":["倾析时动作要慢，避免搅起沉淀。","玻璃棒引流防止液体溅出。"]},
"precipitate-washing":{"apparatus":["漏斗","抽滤瓶","试管"],"observation":"洗涤初期滤液遇硝酸银变浑浊，多次洗涤后不变浑浊。","conclusion":"洗涤至检验不出杂质离子即为洗涤完全。","cautions":["硝酸银腐蚀皮肤。","洗涤时不要搅动滤纸。"]},
"weighing":{"apparatus":["托盘天平","称量纸","药匙","砝码"],"observation":"指针指在分度盘中央。","conclusion":"托盘天平精确到 0.1 g，遵循左物右码。","cautions":["药品不能直接放在托盘上。","称量完毕及时清理。"]},
"volumetric-flask":{"apparatus":["100 mL 容量瓶","烧杯","玻璃棒","胶头滴管","天平"],"observation":"液面凹液面最低处与刻度线相切。","conclusion":"容量瓶用于配制准确浓度的溶液，定容后摇匀。","cautions":["容量瓶不能加热，不能长期存放溶液。","定容时视线与刻度线平齐。"]},
"pipette":{"apparatus":["25 mL 移液管","洗耳球","烧杯"],"observation":"液面与刻度线相切，放液后管尖残留少量液体。","conclusion":"移液管不能加热，读数时视线与刻度线平齐。","cautions":["严禁用嘴吸液。","移液管尖残留液不能吹出。"]},
"burette":{"apparatus":["酸式滴定管","铁架台","滴定台","烧杯"],"observation":"液面稳定，尖嘴无气泡。","conclusion":"滴定管读数精确到 0.01 mL，使用前必须润洗和排气。","cautions":["酸式滴定管不能装碱性溶液。","读数时视线与凹液面最低处平齐。"]},
"gas-collection":{"apparatus":["集气瓶","水槽","导管","玻璃片"],"observation":"不同方法收集到的气体纯度不同。","conclusion":"难溶气体用排水法；密度大于空气用向上排空气法；密度小于空气用向下排空气法。","cautions":["氢气收集时远离火源。","有毒气体不能用排空气法直接排放。"]},
"sublimation":{"apparatus":["蒸发皿","圆底烧瓶","酒精灯","通风橱"],"observation":"产生紫色蒸气，烧瓶底部析出紫黑色晶体。","conclusion":"升华法适用于易升华且杂质不挥发的物质提纯。","cautions":["碘蒸气有毒，操作在通风橱中进行。","加热温度不宜过高。"]},
"fractional-distillation":{"apparatus":["分馏柱","蒸馏烧瓶","冷凝管","温度计","接收瓶"],"observation":"温度计读数稳定在乙醇沸点附近时馏出较快。","conclusion":"分馏可分离沸点相近的液体混合物。","cautions":["乙醇易燃，严禁明火直接加热。","分馏柱保温可提高分离效果。"]},
"steam-distillation":{"apparatus":["水蒸气发生器","蒸馏烧瓶","冷凝管","分液漏斗"],"observation":"馏出液浑浊，静置后分层。","conclusion":"水蒸气蒸馏适用于不溶于水、随水蒸气挥发的物质。","cautions":["苯胺有毒，操作通风并戴手套。","防止蒸汽导管堵塞。"]},
"salting-out":{"apparatus":["烧杯","玻璃棒","漏斗"],"observation":"溶液分层，上层为肥皂。","conclusion":"盐析可分离胶体物质，常用于肥皂和蛋白质的提纯。","cautions":["肥皂液碱性，避免入眼。","热液烫伤风险。"]},
"dialysis":{"apparatus":["半透膜袋","烧杯","试管"],"observation":"袋外液体遇硝酸银变浑浊，遇碘不变蓝。","conclusion":"渗析可除去胶体中的小分子和离子。","cautions":["硝酸银腐蚀皮肤。","半透膜要扎紧，防止泄漏。"]},
"centrifugation":{"apparatus":["离心机","离心管","滴管"],"observation":"沉淀集中在管底，上层液澄清。","conclusion":"离心分离适用于细小悬浮颗粒的分离。","cautions":["离心管必须对称平衡。","离心机未停稳前不得开盖。"]},
"acid-base-standard":{"apparatus":["酸式滴定管","锥形瓶","天平","容量瓶"],"observation":"终点时溶液由黄变橙，半分钟内不褪色。","conclusion":"基准物质法可准确标定酸溶液浓度。","cautions":["盐酸具有腐蚀性。","滴定管使用前要润洗排气。"]},
"redox-titration":{"apparatus":["酸式滴定管","锥形瓶","水浴"],"observation":"滴定初期褪色慢，后期加快，终点呈浅粉红色。","conclusion":"高锰酸钾自身可作指示剂，滴定需控制温度和酸度。","cautions":["高锰酸钾强氧化性，避免接触皮肤。","加热温度不宜过高，防止草酸分解。"]},
"edta-titration":{"apparatus":["酸式滴定管","锥形瓶"],"observation":"终点时溶液由酒红色变为纯蓝色。","conclusion":"配位滴定可测定水的总硬度。","cautions":["氨水有刺激性，操作通风。","缓冲溶液现配现用。"]},
"mohr-method":{"apparatus":["酸式滴定管","锥形瓶"],"observation":"终点时白色沉淀中带砖红色。","conclusion":"莫尔法适用于中性或弱碱性条件下测定氯离子。","cautions":["硝酸银腐蚀皮肤并染色。","滴定过程要避光。"]},
"density-measure":{"apparatus":["比重瓶","天平","量筒"],"observation":"不同液体质量不同。","conclusion":"比重瓶法可较准确测定液体密度。","cautions":["比重瓶要恒温。","装液时避免气泡。"]},
"melting-point":{"apparatus":["熔点测定管","温度计","毛细管","酒精灯"],"observation":"苯甲酸在 122 ℃ 左右熔化。","conclusion":"熔点测定可判断物质纯度。","cautions":["加热要缓慢均匀。","温度计不要接触管壁。"]},
"ph-measure":{"apparatus":["pH 计","玻璃棒","表面皿"],"observation":"酸性溶液 pH 小于 7，碱性大于 7。","conclusion":"pH 计精度高于试纸，测量前需校准。","cautions":["酸碱溶液具有腐蚀性。","pH 计电极使用后清洗保存。"]},
"water-hardness":{"apparatus":["滴定管","锥形瓶","移液管"],"observation":"井水消耗 EDTA 体积大于自来水。","conclusion":"硬水中钙镁离子含量较高，可煮沸或离子交换软化。","cautions":["氨水有刺激性。","滴定终点颜色变化要仔细观察。"]},
"esterification":{"apparatus":["圆底烧瓶","回流冷凝管","蒸馏装置","分液漏斗"],"observation":"馏出液有果香味。","conclusion":"酯化反应可逆，浓硫酸催化和吸水。","cautions":["浓硫酸腐蚀性强，混合时缓慢加入。","乙醇易燃，远离明火。"]},
"saponification":{"apparatus":["烧杯","水浴","玻璃棒","纱布"],"observation":"混合物变稠，盐析后肥皂浮起。","conclusion":"皂化反应生成高级脂肪酸钠，即肥皂主要成分。","cautions":["氢氧化钠腐蚀性强。","热皂液烫伤风险。"]},
"biuret-test":{"apparatus":["试管","滴管"],"observation":"溶液变为紫色。","conclusion":"双缩脲反应可检验蛋白质或肽键。","cautions":["氢氧化钠腐蚀性强。","硫酸铜溶液有刺激性。"]},
"cellulose-hydrolysis":{"apparatus":["试管","水浴","滴管"],"observation":"出现砖红色沉淀。","conclusion":"纤维素水解最终生成葡萄糖。","cautions":["浓硫酸腐蚀性强，稀释时酸入水。","水浴加热注意烫伤。"]},
"fermentation":{"apparatus":["锥形瓶","导管","水浴"],"observation":"产生气泡，石灰水变浑浊，有酒味。","conclusion":"酵母使糖类发酵生成乙醇和二氧化碳。","cautions":["发酵容器不要完全密封，防止胀裂。","产物乙醇易燃。"]},
"bromine-unsaturation":{"apparatus":["试管","滴管","通风橱"],"observation":"植物油使溴水褪色；苯萃取溴使水层褪色、有机层呈橙色。","conclusion":"溴水可区分加成褪色与萃取。","cautions":["溴水有毒，操作通风。","苯有致癌性，避免吸入。"]},
"golden-rain":{"apparatus":["烧杯","水浴","玻璃棒"],"observation":"冷却过程中析出闪亮的金黄色片状晶体。","conclusion":"碘化铅溶解度随温度升高而增大，冷却结晶形成片状晶体。","cautions":["铅盐有毒，避免接触和误食。","废液集中处理。"]},
"silver-tree":{"apparatus":["试管","镊子"],"observation":"铜丝表面析出银白色晶体，溶液逐渐变蓝。","conclusion":"铜置换银，说明铜的还原性比银强。","cautions":["硝酸银腐蚀皮肤并染色。","废液回收银。"]},
"oscillating-reaction":{"apparatus":["烧杯","磁力搅拌器","量筒"],"observation":"溶液在无色与蓝色之间周期性变化。","conclusion":"非线性动力学可产生时间上的周期振荡。","cautions":["溴酸盐强氧化性，避免与有机物干混。","硫酸铈铵有刺激性。"]},
"milk-rainbow":{"apparatus":["浅盘","棉签"],"observation":"色素迅速向外扩散形成彩虹图案。","conclusion":"表面活性剂改变表面张力，产生宏观流动。","cautions":["实验后的牛奶不可食用。","色素可能染色衣物。"]},
"sodium-acetate-crystal":{"apparatus":["烧杯","水浴","玻璃棒"],"observation":"溶液迅速结晶，杯壁发热。","conclusion":"结晶放热，过饱和溶液可作热袋。","cautions":["结晶放热，避免烫伤。","溶液不要溅入眼睛。"]},
"luminol":{"apparatus":["烧杯","滴管","暗室"],"observation":"溶液发出蓝色荧光，逐渐减弱。","conclusion":"化学发光是化学能直接转化为光能。","cautions":["氢氧化钠和过氧化氢腐蚀性强。","在暗处操作注意安全。"]},
"flame-dry-tube":{"apparatus":["试管","试管夹","酒精灯","石棉网"],"observation":"液体逐渐沸腾，试管无裂纹。","conclusion":"均匀预热是玻璃仪器加热安全的关键。","cautions":["管口严禁对着自己或他人。","热试管不能立即用冷水冲洗。"]},
"glass-cutting-bending":{"apparatus":["玻璃管","三角锉","酒精喷灯","石棉网"],"observation":"断口经烧圆后光滑透明，弯管角度均匀。","conclusion":"玻璃加工需先刻痕后折断，再退火减少内应力。","cautions":["折断时戴护目镜并用布包裹。","热玻璃外观与冷玻璃相似，需放置在标识区。"]},
"cork-boring":{"apparatus":["橡胶塞","打孔器","玻璃管","水槽"],"observation":"导管与塞子配合紧密，水中检查无气泡。","conclusion":"打孔质量决定装置气密性，是气体制备实验的基础。","cautions":["打孔器锋利，操作时戴手套。","玻璃管插入塞子时避免用力过猛折断。"]},
"crucible-use":{"apparatus":["坩埚","坩埚钳","马弗炉","干燥器"],"observation":"灼烧后固体仍为白色，质量减少。","conclusion":"坩埚灼烧与干燥器冷却是重量分析的基本操作。","cautions":["坩埚钳使用前预热，避免接触冷水炸裂。","高温炉取放时戴隔热手套。"]},
"thermometer-calibration":{"apparatus":["温度计","烧杯","加热器","标准温度计"],"observation":"温度计在冰水浴中读数可能偏离 0 ℃。","conclusion":"温度计需定期校准，读数才能用于定量实验。","cautions":["沸水实验防止烫伤。","温度计感温泡不要接触杯底。"]},
"ph-meter-calibration":{"apparatus":["pH 计","烧杯","洗瓶","滤纸"],"observation":"校准后缓冲液读数与标称值一致。","conclusion":"两点校准可消除电极老化与温度影响。","cautions":["电极脆弱，避免碰撞。","缓冲液使用后不可倒回原瓶。"]},
"balance-tare":{"apparatus":["电子天平","称量纸","药匙","干燥器"],"observation":"读数稳定后与目标质量偏差小于 0.0002 g。","conclusion":"增量法适合称取指定质量，减量法适合易吸湿样品。","cautions":["不可将药品直接放在天平盘上。","称量完毕及时清理，避免腐蚀天平。"]},
"volumetric-transfer":{"apparatus":["移液管","洗耳球","容量瓶","烧杯"],"observation":"定容后液面最低点与刻度线相切。","conclusion":"移液与定容的准确性直接影响溶液浓度。","cautions":["移液管不可用嘴吸。","定容时视线与刻度线水平。"]},
"reflux-water-separator":{"apparatus":["圆底烧瓶","分水器","回流冷凝管","电热套"],"observation":"分水器底部的水层体积随时间增加。","conclusion":"分水器可连续移出反应生成的水，提高酯化产率。","cautions":["甲苯易燃，装置必须气密并远离明火。","浓硫酸腐蚀性强，加料时冷却。"]},
"vacuum-distillation":{"apparatus":["减压蒸馏装置","真空泵","毛细管","接收瓶"],"observation":"较低温度下即有馏分流出。","conclusion":"减压蒸馏适用于高沸点与热敏物质的提纯。","cautions":["蒸馏结束先解除真空再关泵。","玻璃装置在真空下有内爆风险，需防护。"]},
"electrolyte-conductivity":{"apparatus":["导电性装置","烧杯","电池","灯泡"],"observation":"盐酸与氯化钠溶液灯泡较亮，醋酸较暗，蔗糖溶液不亮。","conclusion":"强电解质导电性强于同浓度弱电解质，非电解质不导电。","cautions":["电极使用后清洗擦干。","避免溶液溅到电源。"]},
"sugar-charring":{"apparatus":["烧杯","玻璃棒","通风橱"],"observation":"白色蔗糖迅速变黑膨胀，放出刺激性气体。","conclusion":"浓硫酸按 2∶1 夺取有机物中的氢氧，体现脱水性。","cautions":["反应放热剧烈并可能喷溅，必须少量并在通风橱内进行。","浓硫酸腐蚀性强，戴手套护目镜。"]},
"iodine-starch-complex":{"apparatus":["试管","水浴锅","滴管"],"observation":"蓝色可逆地随温度消失与恢复。","conclusion":"显色是物理包合而非化学反应，因此具有可逆性。","cautions":["碘液避免接触皮肤与衣物。","加热时管口不对人。"]},
"milk-emulsion":{"apparatus":["试管","滴管","显微镜"],"observation":"牛奶中有细小油滴，加酸后出现白色凝块并分层。","conclusion":"乳浊液靠乳化剂稳定，破坏乳化剂即可破乳。","cautions":["乙酸有刺激性。","显微镜使用后擦净镜头。"]},
"salt-freezing-mixture":{"apparatus":["烧杯","温度计","搅拌棒"],"observation":"温度迅速下降，最低可达 −20 ℃ 左右。","conclusion":"冰盐混合物是常用的低成本低温浴。","cautions":["低温可致冻伤，避免长时间接触。","融化后地面湿滑，及时清理。"]},
"vapor-pressure-demo":{"apparatus":["温度计","棉签","秒表"],"observation":"乙醚降温最快，水最慢。","conclusion":"蒸气压与分子间作用力负相关，蒸发冷却是其宏观表现。","cautions":["乙醚极易燃且具麻醉性，必须在通风橱内少量使用。","避免吸入蒸气。"]},
"capillary-action":{"apparatus":["毛细管","烧杯","刻度尺"],"observation":"水上升最高，洗涤剂溶液最低。","conclusion":"洗涤剂降低水的表面张力，毛细上升随之减小。","cautions":["毛细管易碎，轻拿轻放。","乙醇易燃。"]},
"crystal-growth-alum":{"apparatus":["烧杯","玻璃棒","恒温水浴","晶种"],"observation":"晶种逐渐长大，形成透明八面体。","conclusion":"晶体生长速率越慢，晶形越完整。","cautions":["热溶液避免烫伤。","晶体脆弱，取出时轻拿。"]},
"cobalt-chloride-humidity":{"apparatus":["试管","酒精灯","干燥器"],"observation":"蓝色固体遇水变为粉红色。","conclusion":"结晶水合物的颜色变化可用于指示环境湿度。","cautions":["钴盐有毒且可能致癌，避免接触与吸入。","废液回收处理。"]},
"deliquescence":{"apparatus":["表面皿","干燥器","湿度计"],"observation":"氯化钙与氢氧化钠表面出现液滴，氯化钠变化不明显。","conclusion":"潮解能力与溶解度、吸湿性有关。","cautions":["氢氧化钠腐蚀性强。","称量时避免样品粘在盘上。"]},
"efflorescence":{"apparatus":["表面皿","干燥器","天平"],"observation":"晶体表面逐渐失去光泽，变为白色粉末。","conclusion":"风化是结晶水合物在干燥空气中的自发失水。","cautions":["干燥器使用前检查密封。","称量时避免吸湿。"]},
"gas-diffusion":{"apparatus":["玻璃管","橡胶塞","棉花","秒表"],"observation":"白烟在靠近盐酸一端生成。","conclusion":"氨分子摩尔质量小，扩散速率快，白烟偏向盐酸端。","cautions":["氨与氯化氢气体刺激性强，在通风橱内操作。","玻璃管两端固定，避免滚动。"]},
"colloidal-tyndall":{"apparatus":["激光笔","烧杯","黑纸"],"observation":"氢氧化铁胶体与泥水出现光路，硫酸铜溶液无。","conclusion":"丁达尔效应可用于区分胶体与真溶液。","cautions":["激光笔不可直射眼睛。","氢氧化铁胶体需现制。"]},
"emulsion-test":{"apparatus":["试管","滤纸","激光笔","漏斗"],"observation":"食盐水稳定透明，泥水沉降并被滤纸截留，油水分层。","conclusion":"分散系可按粒子大小与稳定性分类。","cautions":["油水混合物易弄脏台面，及时清理。","激光笔避免直射眼睛。"]},
"suspension-sedimentation":{"apparatus":["量筒","秒表","天平"],"observation":"碳酸钙沉降快，黏土沉降慢且上层浑浊。","conclusion":"颗粒尺寸与形状影响悬浊液稳定性。","cautions":["黏土堵塞下水道，废液静置后处理。","量筒易碎。"]},
"solution-conductivity":{"apparatus":["电导率仪","容量瓶","烧杯"],"observation":"电导率随浓度增加而升高，高浓度区斜率减小。","conclusion":"电导率反映离子浓度与迁移率，可用于定量分析。","cautions":["电极使用后清洗。","避免溶液溅入仪器。"]},
"acid-rain-simulation":{"apparatus":["烧杯","pH 计","天平"],"observation":"表面产生气泡，逐渐出现白色覆盖层，质量减少。","conclusion":"酸雨可腐蚀碳酸盐建筑材料，产物层会阻碍进一步反应。","cautions":["稀硫酸有腐蚀性。","实验后废液交实验员统一处理，不要自行中和。"]},
"hard-water-scum":{"apparatus":["烧杯","酒精灯","pH 试纸"],"observation":"煮沸后出现白色沉淀，加盐酸产生气泡并溶解。","conclusion":"暂时硬度由碳酸氢盐引起，可通过煮沸或酸化去除。","cautions":["盐酸有腐蚀性，操作时戴护目镜。","硬水样品可加氯化钙与碳酸氢钠自制。"]},
"ammonia-solubility":{"apparatus":["圆底烧瓶","滴管","止水夹","玻璃导管"],"observation":"水迅速喷入烧瓶形成喷泉，溶液变红。","conclusion":"氨极易溶于水且溶液显碱性，是喷泉实验的经典气体。","cautions":["氨气刺激呼吸道，在通风橱内操作。","装置气密性要好，避免喷溅。"]},
"chlorine-solubility":{"apparatus":["试管","滴管","通风橱"],"observation":"氯水呈黄绿色，使石蕊先红后褪，品红褪色，遇硝酸银生成白色沉淀。","conclusion":"氯水中含 Cl₂、HClO、H⁺、Cl⁻，兼具酸性、漂白性与氧化性。","cautions":["氯水与氯气有毒，必须在通风橱内操作。","氯水现用现配，避光保存。"]},
"co2-density":{"apparatus":["集气瓶","阶梯蜡烛","烧杯"],"observation":"下层蜡烛先熄灭，石灰水变浑浊。","conclusion":"二氧化碳密度大且不支持燃烧，可用于灭火。","cautions":["蜡烛明火注意防火。","盐酸有腐蚀性。"]},
"hydrogen-diffusion":{"apparatus":["启普发生器","导管","肥皂泡装置"],"observation":"氢气泡点燃时发出爆鸣声并形成淡蓝色火焰。","conclusion":"氢气轻且扩散快，与空气混合点燃易爆。","cautions":["氢气易燃易爆，必须验纯后再点燃，远离明火。","少量操作并在通风处进行。"]},
"gas-molar-volume":{"apparatus":["量气管","水准瓶","分析天平","温度计"],"observation":"量气管中收集到无色气体，体积随反应进行而增加。","conclusion":"通过气体体积与物质的量之比可测定摩尔体积。","cautions":["氢气易燃，实验区禁止明火。","读数前必须使内外液面相平。"]},
"combustion-oxygen-conc":{"apparatus":["集气瓶","燃烧匙","酒精灯"],"observation":"木炭在纯氧中剧烈燃烧、发出白光，在空气中仅红热。","conclusion":"燃烧剧烈程度与氧气浓度正相关。","cautions":["纯氧助燃，操作时远离可燃物。","集气瓶防止炸裂。"]},
"candle-composition":{"apparatus":["烧杯","火柴","镊子"],"observation":"干烧杯内壁出现水雾，石灰水变浑浊。","conclusion":"蜡烛燃烧生成二氧化碳和水，说明石蜡含碳、氢元素。","cautions":["明火操作注意防火与烫伤。","烧杯不要长时间贴近火焰。"]},
"wood-distillation":{"apparatus":["硬质试管","导管","酒精灯","集气瓶"],"observation":"试管口出现黄褐色油状物，气体可燃，残留黑色木炭。","conclusion":"干馏是隔绝空气的热分解，产物随温度变化。","cautions":["木煤气含一氧化碳，必须在通风橱内操作。","加热时防止试管口堵塞。"]},
"sulfur-burn":{"apparatus":["燃烧匙","集气瓶","通风橱"],"observation":"硫在空气中呈淡蓝色火焰，在纯氧中呈明亮蓝紫色。","conclusion":"硫燃烧生成二氧化硫，氧浓度影响火焰颜色与剧烈程度。","cautions":["二氧化硫有毒，必须在通风橱内进行并吸收尾气。","硫粉用量要少。"]},
"phosphorus-burn":{"apparatus":["燃烧匙","集气瓶","水槽","通风橱"],"observation":"产生大量白烟，冷却后瓶内水位上升约 1/5。","conclusion":"红磷燃烧消耗氧气，可用于粗略测定空气中氧气体积分数。","cautions":["白磷剧毒易自燃，本实验只用红磷。","五氧化二磷刺激呼吸道，在通风橱内操作。"]},
"magnesium-co2":{"apparatus":["坩埚钳","集气瓶","酒精灯","通风橱"],"observation":"镁在二氧化碳中继续燃烧，瓶壁出现白色与黑色固体。","conclusion":"镁能在二氧化碳中燃烧，说明其还原性强，金属火灾不能用二氧化碳灭火。","cautions":["镁燃烧强光伤眼，戴护目镜。","金属镁火灾严禁用水与二氧化碳扑救。"]},
"no2-water":{"apparatus":["集气瓶","导管","水槽","通风橱"],"observation":"红棕色褪去，水位上升约 2/3，溶液显酸性。","conclusion":"NO₂ 与水发生歧化反应生成硝酸与 NO。","cautions":["氮氧化物剧毒，全程通风橱与尾气吸收。","集气瓶倒扣时防止漏气。"]},
"electrolysis-na2so4":{"apparatus":["电解槽","石墨电极","直流电源","试管"],"observation":"阴极气体体积约为阳极的两倍，阴极区溶液变碱。","conclusion":"电解水型溶液中，水在两极放电生成氢气和氧气。","cautions":["电解时避免触电，电压不宜过高。","氢气易燃，收集时远离明火。"]},
"electrolysis-hcl":{"apparatus":["电解槽","石墨电极","直流电源","通风橱"],"observation":"阳极气体使试纸变蓝，阴极气体点燃有爆鸣。","conclusion":"电解盐酸时阴离子与阳离子分别放电。","cautions":["氯气有毒，必须在通风橱内电解并吸收尾气。","氢气与氯气混合见光可能爆炸，避免长时间密闭收集。"]},
"electroplating-zinc":{"apparatus":["电镀槽","直流电源","导线","砂纸"],"observation":"铁片表面覆盖银白色锌层。","conclusion":"电镀锌可牺牲阳极保护钢铁。","cautions":["镀液含锌，废液回收。","通电时避免短路。"]},
"electroplating-nickel":{"apparatus":["电镀槽","直流电源","导线","温度计"],"observation":"铜片表面形成光亮镍层。","conclusion":"镀镍层耐腐蚀且美观，镀液成分影响镀层质量。","cautions":["镍盐可能致敏，戴手套操作。","镀液加热时注意防烫。"]},
"electroplating-silver":{"apparatus":["电镀槽","直流电源","导线","通风橱"],"observation":"铜片表面形成银白色镀层。","conclusion":"无氰镀银液可作为教学替代体系，镀层均匀性受电流密度影响。","cautions":["银盐见光分解，镀液避光。","废液含银，必须回收。"]},
"electrolytic-polishing":{"apparatus":["电解槽","直流电源","铅阴极","通风橱"],"observation":"铝片表面由哑光变为镜面光泽。","conclusion":"电解抛光利用阳极溶解的差异整平金属表面。","cautions":["抛光液腐蚀性强，必须戴护具并在通风橱内操作。","避免铝片过度溶解。"]},
"impressed-current":{"apparatus":["电解槽","导线","电源","砂纸"],"observation":"受保护铁片几乎无锈，对照铁片出现锈斑。","conclusion":"阴极保护可显著减缓钢铁的电化学腐蚀。","cautions":["电压不宜过高，避免析氢。","实验后清洗电极。"]},
"voltaic-pile":{"apparatus":["导线","LED","电压表"],"observation":"LED 发光，电压约为每层 0.7 V 累加。","conclusion":"串联原电池可提高输出电压，伏打电堆是最早的化学电源。","cautions":["食盐水避免接触电子元件。","LED 长脚为正极。"]},
"lead-acid-battery":{"apparatus":["蓄电池","充电器","电压表","灯泡"],"observation":"放电时电压逐渐下降，充电后回升。","conclusion":"铅蓄电池通过可逆的氧化还原反应实现电能存储。","cautions":["铅与硫酸均有毒性和腐蚀性，必须戴护具。","充电时可能析出氢气，保持通风。"]},
"conductivity-titration":{"apparatus":["电导率仪","滴定管","磁力搅拌器","烧杯"],"observation":"曲线先下降后上升，折点对应等当点。","conclusion":"电导滴定适合有色或浑浊溶液，无需指示剂。","cautions":["电极保持清洁，避免气泡附着。","滴定过程持续搅拌。"]},
"galvanic-corrosion":{"apparatus":["培养皿","导线","砂纸"],"observation":"铁片接触处出现锈斑，铜片附近琼脂变红。","conclusion":"异种金属接触在电解质中形成电偶，活泼金属加速腐蚀。","cautions":["避免皮肤长时间接触盐水。","实验后清洗金属片。"]},
"methane-chlorination":{"apparatus":["集气瓶","光照装置","通风橱"],"observation":"黄绿色逐渐褪去，瓶内出现油状液滴，试纸变红。","conclusion":"甲烷的氯代是自由基取代，产物随取代程度不同而混合。","cautions":["氯气有毒，甲烷易燃，必须在通风橱内少量操作。","避免强光直射引发剧烈反应。"]},
"ethylene-prep":{"apparatus":["圆底烧瓶","温度计","冷凝管","集气瓶"],"observation":"收集到无色气体，燃烧有明亮火焰，能使溴水褪色。","conclusion":"控制温度是乙醇脱水制乙烯的关键。","cautions":["浓硫酸使乙醇碳化，可能产生二氧化硫，需除杂。","加热迅速越过 140 ℃，避免生成乙醚。"]},
"acetylene-prep":{"apparatus":["锥形瓶","分液漏斗","导管","通风橱"],"observation":"产生无色气体，燃烧有明亮火焰并冒黑烟，使溴水褪色。","conclusion":"乙炔含碳碳三键，可发生加成与氧化反应。","cautions":["乙炔易燃易爆，严禁明火与密闭收集。","电石含硫化钙等杂质，气体有臭味，需除杂。"]},
"benzene-nitration":{"apparatus":["圆底烧瓶","水浴锅","分液漏斗","通风橱"],"observation":"反应液变黄，产物有苦杏仁气味。","conclusion":"苯环发生亲电取代，硝基进入苯环。","cautions":["苯致癌，硝化反应放热剧烈，必须在通风橱内小心控温。","混酸腐蚀性极强，避免喷溅。"]},
"toluene-oxidation":{"apparatus":["圆底烧瓶","回流冷凝管","抽滤装置"],"observation":"紫色褪去，酸化后析出白色片状晶体。","conclusion":"苯环侧链无论长短，只要有 α-氢即被氧化为羧基。","cautions":["甲苯易燃有毒，在通风橱内操作。","高锰酸钾腐蚀性强。"]},
"ethanol-dehydration":{"apparatus":["圆底烧瓶","温度计","冷凝管","集气瓶"],"observation":"140 ℃ 馏出液有乙醚气味，170 ℃ 气体使溴水褪色。","conclusion":"温度决定分子间脱水与分子内脱水的主次。","cautions":["浓硫酸腐蚀性强，乙醇可能碳化产生二氧化硫。","严格控制温度，防止暴沸。"]},
"acetic-acid-fermentation":{"apparatus":["广口瓶","纱布","恒温箱","pH 计"],"observation":"pH 逐渐下降，液面形成菌膜，气味由酒香变为酸香。","conclusion":"醋酸发酵是需氧氧化过程，温度与供氧影响产酸速率。","cautions":["发酵容器需消毒，避免杂菌污染。","不可密封，防止二氧化碳积聚。"]},
"soap-salting":{"apparatus":["烧杯","水浴锅","纱布","模具"],"observation":"皂化液变稠，盐析后肥皂层与液相分层。","conclusion":"皂化是酯的碱性水解，盐析利用溶解度差异分离产物。","cautions":["氢氧化钠腐蚀性强，戴手套护目镜。","热皂液温度高，避免烫伤。"]},
"aspirin-synthesis":{"apparatus":["锥形瓶","水浴锅","抽滤装置","熔点仪"],"observation":"析出白色针状晶体，熔点约 135 ℃。","conclusion":"酚羟基的乙酰化可降低水杨酸的刺激性，产物为阿司匹林。","cautions":["乙酸酐腐蚀性强，避免接触皮肤。","浓硫酸催化，量要少。"]},
"azo-dye":{"apparatus":["烧杯","冰水浴","温度计","抽滤装置"],"observation":"偶合后溶液变为橙红色，析出有色沉淀。","conclusion":"重氮化-偶合是制备偶氮染料的标准方法，温度需严格控制在 5 ℃ 以下。","cautions":["苯胺有毒且致癌，重氮盐不稳定，必须在冰浴与通风橱内操作。","偶氮染料废液按危废处理。"]},
"enzyme-amylase":{"apparatus":["试管","水浴锅","滴板"],"observation":"37 ℃ 组蓝色最浅，80 ℃ 与 0 ℃ 组仍呈蓝色。","conclusion":"酶在最适温度附近活性最高，高温使酶变性失活。","cautions":["唾液样本注意卫生，实验后消毒。","碘液避免接触皮肤。"]},
"starch-gelatinization":{"apparatus":["烧杯","水浴锅","显微镜","玻璃棒"],"observation":"加热后变为半透明黏稠糊，冷却后变硬并析出水分。","conclusion":"糊化与老化是淀粉加工的重要性质。","cautions":["热糊黏稠，搅拌时防止溅出。","显微镜载玻片小心使用。"]},
"protein-isoelectric":{"apparatus":["试管","pH 计","浊度计","移液管"],"observation":"pH 4.6 附近浊度最大，沉淀最多。","conclusion":"蛋白质在等电点溶解度最低，可用于分离纯化。","cautions":["缓冲液配制需准确。","比色皿使用后清洗。"]},
"oil-hydrogenation":{"apparatus":["高压反应釜","氢气瓶","抽滤装置","通风橱"],"observation":"液态油变为半固态脂肪，碘值下降。","conclusion":"氢化提高油脂饱和度与熔点，但可能产生反式脂肪酸。","cautions":["氢气易燃易爆，高压操作需专业设备。","镍催化剂可能自燃，废弃时钝化处理。"]},
"biodiesel":{"apparatus":["圆底烧瓶","回流冷凝管","分液漏斗","通风橱"],"observation":"反应液分层，上层为淡黄色生物柴油。","conclusion":"酯交换将高黏度甘油三酯转化为低黏度脂肪酸甲酯。","cautions":["甲醇有毒易燃，氢氧化钠腐蚀性强，全程通风橱操作。","产物需洗涤除去甘油与碱。"]},
"fingerprint-iodine":{"apparatus":["密闭容器","水浴锅","镊子","通风橱"],"observation":"玻璃片上显现清晰的棕色指纹纹路。","conclusion":"指纹残留的皮脂可吸附碘蒸气，是物理显影方法。","cautions":["碘蒸气有毒且腐蚀金属，必须在通风橱内操作。","容器密封，避免碘外泄。"]},
"paper-making":{"apparatus":["搅拌机","抄纸框","压榨辊","显微镜"],"observation":"得到表面较粗糙的再生纸，纤维交织可见。","conclusion":"造纸是纤维分散、交织与氢键结合的过程。","cautions":["搅拌机使用注意安全。","压榨时避免纸张破损。"]},
"soxhlet-extraction":{"apparatus":["索氏提取器","水浴锅","滤纸筒","旋转蒸发仪"],"observation":"提取液呈淡黄色，溶剂回收后得到油状物。","conclusion":"索氏提取利用溶剂循环提高萃取效率。","cautions":["石油醚易燃，严禁明火，冷凝水必须通畅。","提取器易碎，轻拿轻放。"]},
"rotary-evaporation":{"apparatus":["旋转蒸发仪","真空泵","水浴锅","冷凝管"],"observation":"溶剂在冷凝管中冷凝回流，溶液体积逐渐减少。","conclusion":"旋转蒸发适合热敏物质的温和浓缩。","cautions":["解除真空前先停止加热与旋转。","蒸发瓶装液不超过一半，防止暴沸。"]},
"hot-filtration":{"apparatus":["漏斗","热水漏斗","滤纸","烧杯"],"observation":"滤纸上残留深色杂质，滤液澄清。","conclusion":"热过滤是重结晶提纯的关键步骤。","cautions":["热溶液烫伤风险，戴手套操作。","漏斗预热不足会导致晶体堵塞滤纸。"]},
"crystallization-seeding":{"apparatus":["烧杯","恒温水浴","晶种","镊子"],"observation":"加入晶种后晶体逐渐长大，溶液保持澄清。","conclusion":"晶种可诱导结晶并控制晶形与粒度。","cautions":["过饱和溶液不稳定，避免震动。","晶体易碎，取出时轻拿。"]},
"ion-exchange":{"apparatus":["交换柱","烧杯","pH 计","肥皂水"],"observation":"流出液与肥皂振荡产生丰富泡沫，原硬水泡沫少。","conclusion":"离子交换可去除钙镁离子，实现水的软化。","cautions":["树脂需预处理，避免干柱。","再生废液含高盐，集中处理。"]},
"thin-layer-chromatography":{"apparatus":["层析缸","毛细管","紫外灯","尺子"],"observation":"分离出胡萝卜素、叶黄素与叶绿素等色带。","conclusion":"薄层色谱可快速分离与鉴定混合物组分。","cautions":["展开剂易燃，层析缸加盖并远离火源。","硅胶粉尘刺激呼吸道。"]},
"column-chromatography":{"apparatus":["层析柱","锥形瓶","滴管"],"observation":"柱中形成不同色带，先后流出不同染料。","conclusion":"柱色谱适合制备量分离，固定相与洗脱剂选择是关键。","cautions":["装柱避免气泡与干裂。","染料废液集中处理。"]},
"ultrafiltration":{"apparatus":["超滤装置","注射器","离心管","双缩脲试剂"],"observation":"滤液含氯离子但不含蛋白质，截留液含蛋白质。","conclusion":"超滤可按分子大小分离，用于蛋白质脱盐。","cautions":["超滤膜易破，按说明操作。","离心配平，避免损坏转子。"]},
"density-gradient":{"apparatus":["量筒","滴管","密度计"],"observation":"不同小球停留在不同高度。","conclusion":"密度梯度可用于按密度分离与鉴定物质。","cautions":["叠加时避免搅动，保持液层稳定。","蔗糖溶液易滋生微生物，实验后清洗。"]},
"magnetic-separation":{"apparatus":["磁铁","烧杯","玻璃棒","滤纸"],"observation":"黑色固体被磁铁吸附在杯壁，砂粒留在液相。","conclusion":"磁分离适合分离铁磁性物质，操作简便。","cautions":["磁铁避免靠近电子设备与磁卡。","废液静置后处理。"]},
"titration-curve":{"apparatus":["滴定管","pH 计","磁力搅拌器","烧杯"],"observation":"曲线在等当点附近出现陡峭突跃。","conclusion":"滴定曲线可指导指示剂选择，强酸强碱滴定突跃范围宽。","cautions":["pH 电极脆弱，搅拌时避免碰撞。","酸与碱均有腐蚀性。"]},
"iodometric-vitc":{"apparatus":["滴定管","锥形瓶","分析天平","研钵"],"observation":"终点时溶液出现稳定的蓝色。","conclusion":"维生素 C 具有还原性，可被碘定量氧化。","cautions":["维生素 C 易被空气氧化，操作要迅速。","碘液避免接触皮肤。"]},
"gravimetric-chloride":{"apparatus":["分析天平","坩埚","马弗炉","抽滤装置"],"observation":"生成白色凝乳状沉淀，灼烧后为灰白色固体。","conclusion":"重量法通过称量难溶沉淀的质量确定待测组分含量。","cautions":["硝酸银腐蚀皮肤且见光分解，避光操作。","氯化银沉淀需避光陈化，防止分解。"]},
"dissolved-oxygen":{"apparatus":["溶解氧瓶","滴定管","移液管"],"observation":"固定时生成棕色沉淀，酸化后溶液呈黄色。","conclusion":"溶解氧含量反映水体自净能力与污染程度。","cautions":["碱液腐蚀性强，注意防护。","水样采集后应立即固定，避免曝气。"]},
"colorimetry-iron":{"apparatus":["分光光度计","容量瓶","比色皿"],"observation":"溶液呈橙红色，吸光度随铁浓度线性增加。","conclusion":"比色法灵敏度高，适合微量金属离子测定。","cautions":["显色剂避光保存。","比色皿透光面不可用手指触摸。"]},
"flame-photometry":{"apparatus":["火焰光度计","容量瓶","移液管"],"observation":"钠火焰呈黄色，钾呈紫色，读数随浓度升高。","conclusion":"火焰光度法适合碱金属与碱土金属的快速定量。","cautions":["燃气使用遵守安全规程，防止回火。","标准溶液避免污染。"]},
"viscosity-measure":{"apparatus":["乌氏黏度计","恒温水浴","秒表","洗耳球"],"observation":"甘油流出时间最长，水最短。","conclusion":"黏度反映分子间作用力与分子链缠结程度。","cautions":["黏度计易碎，清洗时轻拿轻放。","恒温时间足够，避免温度波动。"]},
"surface-tension-measure":{"apparatus":["表面张力仪","恒温水浴","铂环"],"observation":"洗涤剂使表面张力明显下降。","conclusion":"表面活性剂降低水的表面张力，是其去污作用的基礎。","cautions":["铂环易变形，操作轻柔。","溶液表面避免振动。"]},
"heat-of-combustion":{"apparatus":["氧弹量热计","氧气瓶","分析天平","温度计"],"observation":"点火后水温明显上升。","conclusion":"燃烧热是物质的重要热力学数据，可用于计算反应焓变。","cautions":["氧弹高压操作危险，必须由专业人员指导。","氧气瓶远离油脂与明火。"]},
"equilibrium-constant":{"apparatus":["分光光度计","容量瓶","比色皿"],"observation":"溶液呈红色，颜色深度随浓度变化。","conclusion":"平衡常数由热力学决定，与初始浓度无关。","cautions":["硝酸腐蚀性强。","配合物见光分解，避光测定。"]},
"rate-order":{"apparatus":["烧杯","秒表","量筒"],"observation":"浓度越高，蓝色出现越快。","conclusion":"通过初速率法可确定反应级数与速率常数。","cautions":["过氧化氢腐蚀皮肤，避免接触。","反应温度需保持恒定。"]},
"crystal-garden":{"apparatus":["烧杯","镊子","护目镜"],"observation":"晶体上长出蓝、绿、粉等彩色枝状物。","conclusion":"半透膜与渗透作用驱动晶体花园生长。","cautions":["硅酸钠强碱性，腐蚀皮肤与眼睛，戴护目镜。","实验后不可搅动，避免破坏结构。"]},
"copper-tree":{"apparatus":["烧杯","镊子","砂纸"],"observation":"锌片表面覆盖红色铜，溶液蓝色变浅。","conclusion":"活动性强的金属可置换出活动性弱的金属。","cautions":["硫酸铜有毒，避免入口。","反应放热，注意溶液温度。"]},
"rubber-egg":{"apparatus":["玻璃杯","保鲜膜"],"observation":"蛋壳溶解，蛋变为半透明弹性球；清水中膨胀，糖浆中皱缩。","conclusion":"渗透作用使水从低浓度向高浓度一侧移动。","cautions":["醋有刺激性，避免溅入眼睛。","生鸡蛋可能带菌，实验后洗手。"]},
"invisible-ink":{"apparatus":["纸","吹风机","熨斗"],"observation":"加热后字迹变为棕色，碱写处遇指示剂变绿。","conclusion":"隐形墨水利用受热碳化或酸碱变色原理。","cautions":["加热时纸可能燃烧，使用低温熨斗并看管。","小苏打与指示剂避免入口。"]},
"ph-rainbow":{"apparatus":["试管架","试管","滴管"],"observation":"试管呈现红、橙、黄、绿、蓝、紫的连续色阶。","conclusion":"混合指示剂可半定量显示 pH 变化。","cautions":["强酸强碱有腐蚀性，戴护目镜。","指示剂含乙醇，远离明火。"]},
"pharaoh-snake":{"apparatus":["耐火托盘","火柴","通风橱"],"observation":"燃烧后长出黑色蓬松碳柱。","conclusion":"碳酸氢钠分解产生气体，使碳化糖膨胀成多孔结构。","cautions":["明火与燃烧产物有风险，必须在通风橱内小量演示。","禁止使用其他含汞或剧毒配方。"]},
"magnesium-burn":{"apparatus":["坩埚钳","酒精灯","护目镜"],"observation":"发出耀眼白光，生成白色疏松固体。","conclusion":"镁与氧反应放热剧烈，产物为氧化镁。","cautions":["强光伤眼，必须戴护目镜且不可直视。","镁火温度高，远离可燃物，禁止用水扑救。"]},
"artificial-snow":{"apparatus":["烧杯","勺子"],"observation":"白色粉末迅速膨胀为蓬松雪状物。","conclusion":"高吸水性树脂通过氢键与渗透压吸水。","cautions":["树脂不可入口，避免儿童误食。","洒落后少量多次清理，防滑。"]},
"glass-etching":{"apparatus":["塑料容器","毛刷","通风橱","护目镜"],"observation":"未涂蜡处变为磨砂，图案清晰。","conclusion":"氢氟酸可腐蚀二氧化硅，是玻璃加工的经典方法。","cautions":["氢氟酸剧毒且腐蚀骨骼，必须戴丁腈手套与面罩，在通风橱内操作。","废液按危险废物回收，由实验员处理。"]},
"cyanotype":{"apparatus":["刷子","晒版框","水盆","通风橱"],"observation":"曝光处变为深蓝色，未曝光处被水洗去。","conclusion":"蓝晒是铁盐光化学与配位显色的结合。","cautions":["铁氰化钾遇酸产生剧毒氢氰酸，严禁与酸混合。","操作戴手套，废液避光回收。"]},
"lava-lamp":{"apparatus":["透明塑料瓶","漏斗"],"observation":"彩色水珠在油层中上升、下沉，形成循环。","conclusion":"密度差与气体浮力共同驱动液滴运动。","cautions":["泡腾片不可入口。","瓶盖拧紧，防止液体溢出。"]},
"density-column":{"apparatus":["烧杯 5 个","量筒","滴管","长玻璃杯","搅拌棒"],"observation":"颜色层清晰分开，低浓度层浮在上方；久置后因扩散逐渐混合。","conclusion":"密度差是分层的原因；加液越慢、温差越小，分层保持越久。","cautions":["使用食品级色素和糖，但实验后不要饮用。","玻璃杯易碎，操作轻拿轻放。","洒落的糖水及时擦净，避免滑倒。"]},
"iodine-fingerprint":{"apparatus":["带盖染色缸","水浴锅","镊子","护目镜","通风橱"],"observation":"滤纸先均匀染成浅棕色，指纹脊线处颜色更深，逐渐显出清晰纹路。","conclusion":"碘的升华—凝华与溶解富集共同作用；温度过高会使背景过深，反而看不清。","cautions":["碘蒸气有毒性和腐蚀性，必须通风橱操作，佩戴护目镜。","不要直接加热碘，避免大量蒸气逸出。","孕妇、甲状腺疾病者不要参与。"]},
"leaf-vein-bookmark":{"apparatus":["烧杯","电热板","镊子","软毛刷","护目镜","手套"],"observation":"叶片由绿变黄褐，叶肉软烂易刷除，叶脉保持完整网状。","conclusion":"碱煮时间依叶片厚度调整；过度碱煮会使叶脉脆断。","cautions":["热碱液腐蚀性强，必须戴护目镜和手套，禁止徒手取叶。","碱液不要倒入铝制容器。","过氧化氢避免接触眼睛和伤口。"]},
"tofu-coagulation":{"apparatus":["锅","温度计","搅拌棒","纱布","豆腐模具"],"observation":"豆浆由均匀乳白变为絮状凝块，上层析出淡黄色清液。","conclusion":"凝固剂种类影响口感：石膏偏嫩，内酯偏滑；温度过高或过低都不易成形。","cautions":["只用食品级凝固剂和干净器具。","热豆浆易烫伤，搅拌时避免溅出。","成品应当天冷藏食用。"]},
"anthocyanin-ph":{"apparatus":["烧杯","研钵","纱布","试管 6 支","滴管"],"observation":"酸性偏红，中性偏紫，碱性偏蓝绿；颜色变化连续但不宜作为精确 pH 计。","conclusion":"花青素是天然酸碱指示剂；不同来源的指示剂变色范围略有差异。","cautions":["提取液不可饮用。","肥皂水不可入眼，避免与食物混放。","实验后器具彻底清洗。"]},
"leaf-pigment-chromatography":{"apparatus":["研钵","漏斗","毛细管","层析缸","剪刀"],"observation":"从下到上依次出现黄绿色、蓝绿色、黄色、橙黄色色带。","conclusion":"极性小的胡萝卜素移动最快；Rf 值可用于初步鉴定色素。","cautions":["乙醇和展开剂易燃，远离明火。","在通风处操作，避免吸入溶剂蒸气。","菠菜提取液易变质，现配现用。"]},
"water-rocket":{"apparatus":["500 mL 饮料瓶","专用水火箭发射器与打气筒","发射架","护目镜","卷尺"],"observation":"水从瓶口向后喷出，瓶体向前上方飞起；水量过多或过少都飞不远。","conclusion":"反冲来自向后喷出的水；水量约三分之一时飞行效果通常较好。","cautions":["必须使用专用水火箭发射器，不要用自制木塞近距离加压。","发射方向朝空旷天空，严禁对人、动物或建筑物。","戴护目镜；瓶体鼓包、老化或出现裂纹立即更换。","打气时人不要俯身在瓶体正上方。"]},
"baking-soda-rocket":{"apparatus":["带卡扣盖的小塑料盒或胶片罐","护目镜","托盘","纸巾"],"observation":"盖子被气体顶开，少量泡沫溅出；反应结束后溶液变温和。","conclusion":"酸与碳酸氢盐反应生成二氧化碳，气体膨胀对外做功。","cautions":["只能用带卡扣的薄塑料小容器，严禁用玻璃瓶、金属罐或硬质密封管。","不要加大用量，不要用重物压住盖子。","戴护目镜，脸和眼睛不要正对盖子。","反应后彻底清理，避免滑倒。"]},
"balloon-rocket":{"apparatus":["气球","吸管","细线","胶带","玩具小车或纸盒","剪刀"],"observation":"气球放气时小车沿相反方向前进；气球越大，跑得越远。","conclusion":"反冲运动不需要燃料，喷出气体的动量与车体动量方向相反。","cautions":["气球碎片可能被儿童误吞，实验后及时清理。","不要对着人脸放气。","剪刀使用注意安全。"]},
"effervescent-rocket":{"apparatus":["带卡扣盖的小塑料盒","护目镜","托盘"],"observation":"盖子被顶开，少量水雾溅出；水中持续冒泡。","conclusion":"泡腾片遇水产生二氧化碳，气体膨胀对外做功。","cautions":["只用薄塑料小盒，严禁玻璃瓶或硬质密封容器。","不要加大用量或压住盖子。","戴护目镜，不要正对盖子。","实验后清理干净，避免儿童误食。"]},
"ops-glassware-drying":{"apparatus":["烧杯","试管刷","烘箱","晾干架"],"observation":"洗净的器壁水膜连续，不出现水珠或白色水痕。","conclusion":"仪器清洁度直接影响体积准确性与反应结果，计量仪器优先晾干。","cautions":["容量瓶、滴定管不可烘烤。","洗涤剂需冲净，避免影响后续滴定。"]},
"ops-pipette-calibration":{"apparatus":["移液管","分析天平","称量瓶","温度计"],"observation":"三次移取体积接近，但可能比标称值略大或略小。","conclusion":"移液管存在允许误差；精密分析应使用校准后的实际体积。","cautions":["移液管尖不得碰壁，放液后停留约 15 秒。","称量瓶应加盖，减少蒸发。"]},
"ops-burette-cleaning":{"apparatus":["酸式滴定管","滴定台","烧杯","凡士林"],"observation":"检漏时尖嘴无水滴持续渗出，液面可稳定在零刻度。","conclusion":"滴定管必须洁净、密封并以待装液润洗，才能保证滴定体积准确。","cautions":["旋塞涂油要薄而匀，避免堵孔。","装液后先排尽尖嘴气泡再读数。"]},
"ops-desiccator-use":{"apparatus":["干燥器","烘箱","坩埚钳"],"observation":"开盖时有轻微吸附感，说明密封良好。","conclusion":"干燥器用于冷却与保存易吸湿样品，干燥剂需定期检查与再生。","cautions":["不能存放潮湿样品，否则干燥剂迅速失效。","热的坩埚需稍冷后再放入，避免炸裂。"]},
"ops-hot-filtration":{"apparatus":["漏斗","滤纸","锥形瓶","水浴"],"observation":"热滤液澄清，滤纸上留下不溶杂质；冷却后滤液出现晶体。","conclusion":"热过滤的关键是保温与快速，适用于重结晶前的除杂。","cautions":["热溶液易烫伤，佩戴隔热手套。","易燃溶剂禁止用明火加热。"]},
"ops-weighing-difference":{"apparatus":["分析天平","称量瓶","药匙","称量纸"],"observation":"样品转移量可通过差值精确得到，称量瓶内剩余样品仍可密封保存。","conclusion":"减量法适合易吸湿样品，操作时避免药匙接触样品。","cautions":["不能用手直接接触称量瓶内壁。","每次称量前检查天平水平与零点。"]},
"ops-sample-labeling":{"apparatus":["样品瓶","实验记录本"],"observation":"标签清晰的样品在后续取用时无需开盖辨认。","conclusion":"规范标签与记录能显著降低实验室误用与重复劳动。","cautions":["不要只写俗称或缩写。","标签被腐蚀模糊时应立即更换。"]},
"ops-reflux-assembly":{"apparatus":["圆底烧瓶","球形冷凝管","铁架台","水浴"],"observation":"冷凝管内壁持续有液膜回流，烧瓶内液面基本不下降。","conclusion":"回流装置的关键是稳固夹持、正确通水与防暴沸。","cautions":["先通水再加热，结束时先撤热源后停水。","密闭体系禁止加热，必须与大气相通。"]},
"qual-borax-bead":{"apparatus":["铂丝","酒精灯","坩埚钳"],"observation":"钴化合物呈深蓝色，铜化合物在氧化焰中呈蓝绿色。","conclusion":"硼砂珠试验是经典干法鉴定，颜色受焰型和氧化态影响。","cautions":["铂丝贵且易被还原性物质腐蚀，不可蘸强还原剂。","金属氧化物粉尘需避免吸入。"]},
"qual-phosphate":{"apparatus":["试管","胶头滴管","pH 试纸"],"observation":"生成黄色沉淀，加硝酸后沉淀消失。","conclusion":"黄色、溶于稀硝酸的银盐沉淀可辅助判断磷酸根。","cautions":["硝酸银腐蚀皮肤、染黑衣物。","废液中的银离子应回收处理。"]},
"qual-bicarbonate":{"apparatus":["试管","酒精灯","导管"],"observation":"氯化钡不产生沉淀；加热放出使石灰水变浑浊的气体；加酸冒泡。","conclusion":"加热分解与氯化钡对比可区分碳酸氢根与碳酸根。","cautions":["加热试管口不要对着人。","石灰水变浑浊后继续通气会重新变清。"]},
"qual-sulfite":{"apparatus":["试管","胶头滴管","水浴"],"observation":"白色沉淀溶于盐酸，品红褪色，加热后颜色可恢复。","conclusion":"亚硫酸根具有还原性与漂白性，可与硫酸根区分。","cautions":["SO₂ 刺激呼吸道，操作在通风橱进行。","亚硫酸盐废液不能直接排入下水道。"]},
"qual-thiosulfate":{"apparatus":["试管","胶头滴管"],"observation":"酸化后出现淡黄色浑浊；碘水褪色。","conclusion":"酸化分解与还原碘是硫代硫酸根的特征反应。","cautions":["二氧化硫有毒，注意通风。","碘水腐蚀皮肤，避免接触。"]},
"qual-bromide":{"apparatus":["试管","胶头滴管","暗室"],"observation":"淡黄色沉淀，氨水中部分溶解，硫代硫酸钠中溶解。","conclusion":"溴化银的颜色与溶解度介于氯化银和碘化银之间。","cautions":["溴化银见光分解，避免强光直射。","硝酸银与氨水废液分开回收。"]},
"qual-iodide":{"apparatus":["试管","胶头滴管"],"observation":"黄色沉淀在硝酸和氨水中都不溶解。","conclusion":"碘化银的极低溶解度是碘离子检验的重要依据。","cautions":["硝酸银染黑皮肤。","含银废液统一回收。"]},
"qual-nitrite":{"apparatus":["试管","胶头滴管","通风橱"],"observation":"酸化后出现红棕色气体，淀粉碘化钾试纸变蓝。","conclusion":"亚硝酸根在酸性条件下既有氧化性又有不稳定性。","cautions":["亚硝酸盐有毒且可能生成亚硝胺，禁止入口。","红棕色气体在通风橱内操作。"]},
"qual-permanganate-media":{"apparatus":["试管","胶头滴管"],"observation":"酸性褪为近无色，中性出现棕色沉淀，碱性变为绿色。","conclusion":"高锰酸根的还原产物取决于溶液酸碱性。","cautions":["高锰酸钾强氧化，避免与有机物、还原剂混放。","浓碱腐蚀，佩戴护目镜。"]},
"qual-copper-chloride-complex":{"apparatus":["试管","胶头滴管"],"observation":"加盐酸后变黄绿色，稀释后回到蓝绿色。","conclusion":"铜离子与氯离子的配位平衡受配体浓度控制。","cautions":["浓盐酸挥发刺激，通风操作。","铜盐废液回收。"]},
"qual-cobalt-complex":{"apparatus":["试管","水浴","温度计"],"observation":"加盐酸变蓝，加热更蓝，冷却稀释后回粉红。","conclusion":"配位平衡对配体浓度和温度敏感，可用于温度指示。","cautions":["钴盐有潜在致癌性，避免粉尘与接触。","浓盐酸在通风橱中操作。"]},
"qual-nickel-ammonia":{"apparatus":["试管","胶头滴管"],"observation":"先产生绿色沉淀，过量氨水后变为深蓝色溶液。","conclusion":"镍离子能与氨形成稳定配合物，过量配体使沉淀溶解。","cautions":["镍盐可能致敏，避免接触皮肤。","氨水刺激性气味，通风操作。"]},
"qual-iron-oxalate":{"apparatus":["烧杯","紫外灯或强光","试管"],"observation":"照光后的溶液检验出更多 Fe²⁺，颜色变化更明显。","conclusion":"草酸铁配合物具有光敏性，是早期光化学与 blueprint 工艺的基础。","cautions":["避免眼睛直视紫外灯。","铁氰化钾遇酸放出剧毒 HCN，严禁酸化。"]},
"qual-potassium-flame":{"apparatus":["铂丝或镍铬丝","酒精灯","蓝色钴玻璃"],"observation":"直接观察偏黄，透过钴玻璃可见浅紫色。","conclusion":"焰色试验需排除钠干扰，钴玻璃是常用滤光工具。","cautions":["金属丝每次使用前必须洗净灼烧。","酒精灯火焰不要对着人。"]},
"qual-copper-flame":{"apparatus":["铂丝","酒精灯","钴玻璃"],"observation":"火焰呈蓝绿色，持续时间较短。","conclusion":"铜盐的蓝绿色焰色可用于辅助识别铜元素。","cautions":["铜盐有毒，避免入口。","金属丝蘸取量不宜过多。"]},
"qual-strontium-flame":{"apparatus":["铂丝","酒精灯"],"observation":"锶盐呈稳定的洋红色火焰。","conclusion":"焰色反应可快速区分碱土金属元素。","cautions":["锶盐应避免误食。","焰色观察需在暗处对比更明显。"]},
"gas-chlorine-water":{"apparatus":["试管","胶头滴管","通风橱"],"observation":"石蕊先红后褪，布条褪色，硝酸银生成白色沉淀。","conclusion":"氯水同时含 Cl₂、HCl、HClO，兼具酸性、氧化性与漂白性。","cautions":["氯气有毒，全程通风橱操作。","氯水现配现用，避免久置失效。"]},
"gas-sulfur-dioxide":{"apparatus":["燃烧匙","集气瓶","通风橱","导管"],"observation":"品红褪色，高锰酸钾褪色，石蕊变红。","conclusion":"SO₂ 是酸性氧化物，兼具漂白性与还原性。","cautions":["SO₂ 强烈刺激呼吸道，仅限通风橱教师演示。","尾气用碱液吸收，禁止直接排放。"]},
"gas-hydrogen-chloride-fountain":{"apparatus":["圆底烧瓶","导管","止水夹","水槽"],"observation":"水迅速喷入烧瓶，形成红色喷泉。","conclusion":"喷泉实验直观展示 HCl 的高溶解度与酸性。","cautions":["HCl 气体强刺激，必须在通风橱内少量演示。","装置气密性要好，避免倒吸。"]},
"gas-carbon-dioxide-density":{"apparatus":["集气瓶","烧杯","导管","蜡烛"],"observation":"下层蜡烛先熄灭，上层后熄灭。","conclusion":"CO₂ 密度大于空气且不助燃，可用于灭火。","cautions":["密闭空间内 CO₂ 积聚可致窒息。","蜡烛与纸片远离火源管理。"]},
"gas-oxygen-concentration":{"apparatus":["集气瓶","导管","木条","酒精灯"],"observation":"纯氧中木条剧烈复燃，空气中仅微微发红。","conclusion":"氧气浓度显著影响燃烧剧烈程度。","cautions":["氧气瓶远离油脂与火源。","木条火星不要接触瓶壁。"]},
"gas-methane-combustion":{"apparatus":["导管","烧杯","集气瓶","火柴"],"observation":"烧杯内壁出现水珠，石灰水变浑浊。","conclusion":"甲烷燃烧生成水和二氧化碳，证明其含碳、氢元素。","cautions":["点燃前必须验纯，防止爆炸。","通风良好，避免 CO 积聚。"]},
"gas-ethanol-vapor":{"apparatus":["蒸发皿","水浴","导管","火柴"],"observation":"淡蓝色火焰，烧杯出现水雾，石灰水变浑浊。","conclusion":"乙醇蒸气燃烧生成 CO₂ 和 H₂O，属于氧化反应。","cautions":["严禁用明火直接加热乙醇。","装置附近不得有明火，备灭火毯。"]},
"gas-hydrogen-diffusion":{"apparatus":["集气瓶","导管","肥皂泡"],"observation":"氢气快速扩散，肥皂泡上浮。","conclusion":"氢气扩散速率与密度共同决定其逸散行为。","cautions":["氢气必须验纯后再点燃。","室内通风，远离火源。"]},
"gas-effusion":{"apparatus":["长玻璃管","橡胶塞","镊子"],"observation":"白烟在靠近盐酸一端生成。","conclusion":"气体扩散速率与相对分子质量负相关，NH₃ 扩散更快。","cautions":["氨与氯化氢气体刺激，通风橱操作。","玻璃管两端密封，避免气体逸出。"]},
"gas-nitrogen-dioxide-water":{"apparatus":["集气瓶","导管","通风橱","水槽"],"observation":"红棕色气体消失，液面上升，溶液呈酸性。","conclusion":"NO₂ 与水反应生成硝酸，是工业制硝酸的基础。","cautions":["NO₂ 剧毒，仅限通风橱教师演示。","尾气必须用碱液吸收，禁止排放。"]},
"elec-nickel-plating":{"apparatus":["直流电源","镍阳极","铜片","电镀槽"],"observation":"铜片表面覆盖均匀银白色镍层。","conclusion":"电镀利用阴极还原沉积金属，镀液成分与电流密度决定镀层质量。","cautions":["镍盐可能致敏，戴手套操作。","电镀废液含重金属，必须回收处理。"]},
"elec-silver-plating":{"apparatus":["直流电源","银阳极","铜片","电镀槽"],"observation":"铜片表面出现银白色光泽镀层。","conclusion":"配位剂控制银离子浓度，使镀层均匀细致。","cautions":["镀液中的银离子对水生生物有毒。","避免使用氰化物镀液，优先选择低毒配体。"]},
"elec-polishing":{"apparatus":["直流电源","铅或石墨阴极","电解槽","通风橱"],"observation":"表面粗糙度下降，出现镜面光泽。","conclusion":"电解抛光通过选择性阳极溶解改善金属表面。","cautions":["强酸电解液腐蚀性强，通风橱内操作。","避免高电压导致点蚀与过热。"]},
"elec-anodizing":{"apparatus":["直流电源","铅阴极","电解槽","恒温水浴"],"observation":"铝片表面形成均匀氧化膜，染色后颜色牢固。","conclusion":"阳极氧化提高铝的耐蚀性与装饰性，膜厚由电量决定。","cautions":["硫酸腐蚀性强，佩戴护目镜与手套。","氧化过程放热，需控温避免膜层烧焦。"]},
"elec-cathodic-protection":{"apparatus":["烧杯","导线","砂纸"],"observation":"未保护铁片很快出现蓝色，连接锌片的铁片变化很小。","conclusion":"牺牲阳极法可有效保护钢铁免受电化学腐蚀。","cautions":["铁氰化钾遇酸产生剧毒 HCN，禁止酸化。","实验后废液集中处理。"]},
"elec-concentration-cell":{"apparatus":["电压表","盐桥","烧杯","导线"],"observation":"电压表显示几十毫伏，浓侧电极电势较高。","conclusion":"浓差电池把浓度差转化为电能，验证能斯特关系。","cautions":["盐桥两端不要混用。","铜盐废液回收。"]},
"elec-saltwater-corrosion":{"apparatus":["培养皿","导线","砂纸"],"observation":"铁钉与铜丝接触处附近最早出现蓝色。","conclusion":"两种金属接触且处于电解质中会形成腐蚀电池，较活泼金属被腐蚀。","cautions":["铁氰化钾遇酸产生剧毒 HCN，禁止酸化。","实验后废液集中处理。"]},
"elec-coin-battery":{"apparatus":["吸水纸","LED","万用表"],"observation":"电压随单元数增加，LED 微微发光。","conclusion":"伏打电堆把化学能转化为电能，串联提高电压。","cautions":["不要用市电或充电器替代。","铜币与锌片边缘可能割手。"]},
"org-banana-oil":{"apparatus":["圆底烧瓶","冷凝管","分液漏斗","水浴"],"observation":"有机层具有明显香蕉香味。","conclusion":"酯化反应生成酯，羧酸与醇在酸催化下脱水。","cautions":["浓硫酸腐蚀性强，佩戴护目镜。","产物仅作气味演示，不可食用。"]},
"org-methyl-salicylate":{"apparatus":["圆底烧瓶","冷凝管","分液漏斗","水浴"],"observation":"得到具有冬青气味的油状液体。","conclusion":"水杨酸甲酯可由酯化制得，是常见香料与外用药成分。","cautions":["甲醇有毒且易燃，通风橱操作。","产物不可内服，避免接触眼睛。"]},
"org-casein-plastic":{"apparatus":["烧杯","纱布","模具","水浴"],"observation":"酪蛋白形成可塑团块，干燥后变硬。","conclusion":"蛋白质可通过交联改性制成塑料样材料。","cautions":["甲醛有毒且致癌，优先用加热替代。","使用食品材料后不得食用。"]},
"org-starch-plastic":{"apparatus":["烧杯","玻璃板","烘箱","刮刀"],"observation":"得到半透明、柔韧的薄膜。","conclusion":"淀粉与增塑剂可制成可降解材料，力学性能随配比变化。","cautions":["加热时防暴沸与烫伤。","薄膜不可接触高温食品。"]},
"org-chlorophyll":{"apparatus":["研钵","漏斗","紫外灯","试管"],"observation":"滤液呈绿色，紫外灯下出现红色荧光。","conclusion":"叶绿素是天然色素，具有特征吸收与荧光。","cautions":["紫外灯避免直射眼睛与皮肤。","乙醇易燃，远离火源。"]},
"org-curcumin":{"apparatus":["烧杯","滤纸","试管","滴管"],"observation":"碱性变红棕，硼酸显玫瑰红。","conclusion":"姜黄素是天然酸碱指示剂与配位显色剂。","cautions":["氢氧化钠腐蚀性，戴手套。","提取液避免入口。"]},
"org-cellulose-acetate":{"apparatus":["烧杯","水浴","玻璃板","通风橱"],"observation":"得到白色纤维状固体，丙酮中可成膜。","conclusion":"天然高分子经酯化改性可得到热塑性材料。","cautions":["乙酸酐腐蚀性强，通风橱操作。","反应放热，控制温度。"]},
"org-nylon-rope":{"apparatus":["烧杯","镊子","玻璃棒","通风橱"],"observation":"界面生成薄膜，可连续拉出韧性纤维。","conclusion":"界面缩聚可制得聚酰胺纤维，体现高分子链的连续生长。","cautions":["酰氯刺激性强，通风橱操作。","环己烷易燃，远离火源。"]},
"org-urea-resin":{"apparatus":["烧杯","模具","温度计","通风橱"],"observation":"混合物逐渐变稠、放热并硬化为白色固体。","conclusion":"热固性树脂通过交联形成三维网络，固化后不可逆。","cautions":["甲醛有毒且致癌，必须通风橱操作。","固化放热，避免大量配制。"]},
"org-essential-oil":{"apparatus":["研钵","分液漏斗","蒸馏装置","试管"],"observation":"得到有柑橘香气的油状物，溴水褪色。","conclusion":"植物精油可用溶剂提取，主要成分为萜烯。","cautions":["石油醚易燃，远离火源。","精油不可食用或涂抹皮肤。"]},
"sep-froth-flotation":{"apparatus":["量筒","气泵","导管","烧杯"],"observation":"疏水的硫粉随泡沫上浮，二氧化硅留在底部。","conclusion":"浮选利用表面润湿性差异分离颗粒。","cautions":["气泵不要进水。","泡沫溢出及时清理。"]},
"sep-zone-refining":{"apparatus":["玻璃管","加热环","镊子"],"observation":"杂质集中在最后凝固的一端。","conclusion":"区域熔炼可反复移动熔区获得高纯材料。","cautions":["萘易燃且有气味，通风处操作。","玻璃管加热后烫手。"]},
"sep-gel-filtration":{"apparatus":["层析柱","试管","滴管"],"observation":"蓝色大分子先洗出，红色小分子后出。","conclusion":"凝胶过滤按分子尺寸分离，大分子先出。","cautions":["装柱避免气泡与干柱。","凝胶按说明再生保存。"]},
"sep-electrophoresis":{"apparatus":["直流电源","碳电极","培养皿","导线"],"observation":"不同颜色的染料向不同电极迁移。","conclusion":"电泳按电荷与尺寸分离带电物质。","cautions":["使用低压直流电源，避免触电。","电极不要让纸桥干烧。"]},
"sep-acid-base-extraction":{"apparatus":["分液漏斗","烧杯","pH 试纸"],"observation":"水相酸化后出现白色固体，有机相留有油状酯。","conclusion":"酸碱萃取利用可电离性差异分离有机物。","cautions":["乙醚极易燃，严禁明火。","分液时及时放气。"]},
"sep-precipitation-fractionation":{"apparatus":["烧杯","离心管","离心机","透析袋"],"observation":"不同饱和度下析出不同量的蛋白质。","conclusion":"盐析分级可按溶解度粗分蛋白质。","cautions":["离心管配平，避免破裂。","盐析后需透析除盐。"]},
"sep-membrane-osmosis":{"apparatus":["透析袋","玻璃管","刻度尺","烧杯"],"observation":"玻璃管内液面逐渐上升。","conclusion":"半透膜两侧浓度差产生渗透压。","cautions":["透析袋使用前检查是否漏液。","长时间放置会因膜透性变化失真。"]},
"sep-centrifugal-separation":{"apparatus":["离心机","离心管","天平","刻度尺"],"observation":"离心管很快分层，自然静置仍浑浊。","conclusion":"离心可显著加速固液分离。","cautions":["离心管必须对称配平。","转速不要超过管与转子的额定值。"]},
"quant-partition-coefficient":{"apparatus":["分液漏斗","锥形瓶","滴定管","恒温水浴"],"observation":"四氯化碳相碘浓度明显高于水相。","conclusion":"分配系数反映溶质在两相中的相对溶解度。","cautions":["四氯化碳有毒，通风橱操作。","碘腐蚀皮肤，避免直接接触。"]},
"quant-adsorption-isotherm":{"apparatus":["锥形瓶","分光光度计","振荡器","离心机"],"observation":"吸附量随平衡浓度增加而趋于饱和。","conclusion":"活性炭吸附符合 Langmuir 型等温线。","cautions":["亚甲基蓝染色衣物。","活性炭粉尘佩戴口罩。"]},
"quant-enzyme-kinetics":{"apparatus":["试管","秒表","滴定管","水浴"],"observation":"速率随底物浓度增加而趋于饱和。","conclusion":"酶促反应遵循米氏动力学。","cautions":["高锰酸钾与硫酸腐蚀性，戴护目镜。","酶液现配现用。"]},
"quant-refractive-index":{"apparatus":["阿贝折射仪","恒温水浴","滴管"],"observation":"折射率随浓度升高而增大。","conclusion":"折射率可用于快速测定糖液浓度。","cautions":["棱镜用擦镜纸轻擦，避免划伤。","样品需澄清无气泡。"]},
"quant-turbidimetric-sulfate":{"apparatus":["分光光度计","比色管","浊度计"],"observation":"硫酸根浓度越高，悬浊液越浑浊。","conclusion":"浊度法可快速测定水样硫酸根。","cautions":["钡盐有毒，废液回收。","比色管需洁净无划痕。"]},
"quant-standard-addition":{"apparatus":["分光光度计","容量瓶","移液管"],"observation":"吸光度随加入铁量线性增加。","conclusion":"标准加入法适合基体复杂样品的微量测定。","cautions":["邻二氮菲刺激眼睛。","玻璃器皿用稀酸浸泡以去铁。"]},
"quant-gas-analysis":{"apparatus":["气体分析仪","量气管","吸收瓶"],"observation":"每次吸收后气体体积依次减少。","conclusion":"选择性吸收可测定混合气体组成。","cautions":["氯化亚铜与 CO 有毒，通风橱操作。","吸收液避免倒吸。"]},
"quant-thermogravimetric":{"apparatus":["坩埚","马弗炉","分析天平","干燥器"],"observation":"蓝色晶体逐渐变白，质量分步下降。","conclusion":"热重曲线可确定结晶水与热分解步骤。","cautions":["马弗炉高温，使用坩埚钳。","无水硫酸铜易吸潮，称量要快。"]},
"fun-magic-sand":{"apparatus":["托盘","烧杯","手套"],"observation":"沙在水中聚成团，取出仍是干的。","conclusion":"表面疏水化改变润湿性，产生“魔术沙”效果。","cautions":["喷雾在通风处使用，避免吸入。","处理后洗手，材料不可食用。"]},
"fun-superabsorbent":{"apparatus":["剪刀","烧杯","量筒","纱布"],"observation":"纯水中膨胀数百倍，盐水中明显减弱。","conclusion":"高吸水性树脂的吸水能力受离子强度影响。","cautions":["树脂不可食用，避免儿童误食。","吸水后地面湿滑。"]},
"fun-thermochromic":{"apparatus":["吹风机","冰袋","画笔"],"observation":"加热后颜色变浅或消失，冷却后恢复。","conclusion":"热致变色材料的颜色随温度可逆变化。","cautions":["吹风机不要长时间定点加热。","颜料不可入口。"]},
"fun-photochromic":{"apparatus":["紫外灯","纸板","计时器"],"observation":"曝光区显色，遮光区不变；暗处逐渐褪色。","conclusion":"光致变色是光诱导的可逆结构变化。","cautions":["紫外灯避免直射眼睛。","颜料不可接触食物。"]},
"fun-bouncing-ball":{"apparatus":["烧杯","搅拌棒","量筒","刻度尺"],"observation":"凝胶球可回弹，硼砂越多越硬。","conclusion":"交联密度决定高分子凝胶的力学性能。","cautions":["硼砂有毒，避免入口与接触伤口。","PVA 加热防烫伤。"]},
"fun-shape-memory":{"apparatus":["镊子","热水杯","护目镜"],"observation":"热水中合金丝迅速恢复直形。","conclusion":"形状记忆效应来自可逆的马氏体相变。","cautions":["热水烫伤风险，使用镊子。","合金丝端头可能尖锐。"]},
"life-vinegar-acidity":{"apparatus":["滴定管","锥形瓶","移液管"],"observation":"终点出现浅粉色并保持 30 秒。","conclusion":"食醋总酸度一般在 3.5–6 g/100 mL。","cautions":["氢氧化钠腐蚀，戴护目镜。","食醋样品需过滤澄清。"]},
"life-baking-powder":{"apparatus":["气球","锥形瓶","天平","水浴"],"observation":"泡打粉遇水立即产气，酵母缓慢产气。","conclusion":"膨松剂类型决定产气速率与持续时间。","cautions":["气球不要套太紧以免脱落。","温水不超过 40 ℃，避免烫死酵母。"]},
"life-milk-fat":{"apparatus":["离心管","离心机","水浴","刻度尺"],"observation":"全脂牛奶出现明显奶油层，脱脂牛奶几乎没有。","conclusion":"乳浊液的乳析程度与脂肪含量和稳定性有关。","cautions":["离心管配平。","牛奶加热后不要立即密封。"]},
"life-detergent-foam":{"apparatus":["试管","量筒","振荡器","天平"],"observation":"肥皂在硬水中泡沫少且有浮渣，洗洁精受影响较小。","conclusion":"洗涤剂类型与水的硬度共同影响去污效果。","cautions":["洗涤剂避免入眼。","废液不要直接倒入水体。"]},
"life-rust-removal":{"apparatus":["烧杯","砂纸","刷子","计时器"],"observation":"草酸除锈最快，食醋较慢；涂油组锈蚀明显减少。","conclusion":"酸可除锈，涂层可隔绝腐蚀条件。","cautions":["草酸有毒，戴手套，避免接触伤口。","酸液废液交实验员统一处理，不要自行中和。"]},
"life-water-softening":{"apparatus":["烧杯","漏斗","试管","量筒"],"observation":"离子交换后肥皂水用量最少，煮沸效果有限。","conclusion":"不同软化方法对暂时/永久硬度效果不同。","cautions":["石灰水腐蚀，戴护目镜。","树脂按说明再生。"]},
"life-water-filter":{"apparatus":["塑料瓶","纱布","烧杯","浊度计"],"observation":"滤液变清、异味减少，但仍可能含盐。","conclusion":"分层过滤可改善感官指标，不能保证饮用安全。","cautions":["自制滤水器不得直接饮用。","活性炭需定期更换。"]},
"env-water-ph":{"apparatus":["pH 计","比色卡","烧杯","温度计"],"observation":"pH 计读数稳定，试纸误差约 ±0.5。","conclusion":"现场筛查可用试纸，精确测定需校准 pH 计。","cautions":["pH 计电极脆弱，轻拿轻放。","水样可能含病原体，戴手套。"]},
"env-water-conductivity":{"apparatus":["电导率仪","烧杯","温度计"],"observation":"纯净水最低，矿泉水与自来水居中，盐水最高。","conclusion":"电导率可快速反映水中离子总量。","cautions":["电极使用后用去离子水冲洗。","不同水样避免交叉污染。"]},
"env-residual-chlorine":{"apparatus":["比色管","分光光度计","滴管"],"observation":"自来水余氯约 0.2–0.8 mg/L，放置后下降。","conclusion":"余氯比色法可评价消毒效果与管网余量。","cautions":["DPD 试剂避免接触眼睛。","显色后尽快比色。"]},
"env-nitrate":{"apparatus":["比色管","分光光度计","试纸"],"observation":"高浓度水样呈明显粉红色。","conclusion":"硝酸盐超标提示农业面源或生活污水污染。","cautions":["镉及其盐有毒，废液回收。","试纸法仅作半定量筛查。"]},
"env-phosphate":{"apparatus":["分光光度计","比色管","水浴"],"observation":"含磷洗涤剂水样显色明显更深。","conclusion":"磷酸盐超标是水体富营养化的重要指标。","cautions":["硫酸腐蚀，戴护目镜。","抗坏血酸现配现用。"]},
"env-turbidity":{"apparatus":["浊度计","烧杯","搅拌器","计时器"],"observation":"聚合氯化铝絮体大、沉降快，浊度下降明显。","conclusion":"絮凝可有效降低浊度，效果与药剂类型、pH 有关。","cautions":["絮凝剂避免吸入粉尘。","上清液不等于可饮用。"]},
"env-soil-ph":{"apparatus":["pH 计","烧杯","搅拌器","离心管"],"observation":"腐殖土 pH 变化小于砂土。","conclusion":"土壤缓冲性影响其抗酸碱冲击能力。","cautions":["土壤样品可能含病原体与重金属。","酸碱操作戴护目镜。"]},
"env-air-co2":{"apparatus":["CO₂ 传感器","气泵","吸收瓶","计时器"],"observation":"通风后 CO₂ 浓度明显下降。","conclusion":"通风是改善室内空气质量的有效手段。","cautions":["氢氧化钡有毒，避免接触。","传感器定期校准。"]},
"env-acid-rain":{"apparatus":["烧杯","天平","计时器","镊子"],"observation":"pH 2 组气泡明显，表面粗糙，质量损失最大。","conclusion":"酸雨会侵蚀碳酸盐建材，pH 越低破坏越强。","cautions":["硫酸腐蚀，戴护目镜与手套。","大理石碎片避免割伤。"]},
"env-ammonia-nitrogen":{"apparatus":["分光光度计","比色管","蒸馏装置"],"observation":"污染水样显色明显加深。","conclusion":"氨氮是评价水体有机污染的重要指标。","cautions":["纳氏试剂含汞，废液必须回收。","通风橱操作，避免吸入。","本实验只做低浓度教学样品。"]},
"env-cod":{"apparatus":["回流装置","滴定管","锥形瓶","通风橱"],"observation":"空白与样品消耗体积差对应有机质含量。","conclusion":"COD 反映水体中可被强氧化剂分解的还原性物质。","cautions":["重铬酸钾与汞盐剧毒，必须通风橱与专业废液回收。","仅限教师演示或专业实验室，不开放学生独立操作。"]},
"env-bod":{"apparatus":["BOD 瓶","溶解氧探头","恒温培养箱"],"observation":"有机污染水样 DO 明显下降。","conclusion":"BOD₅ 反映可生物降解有机物的量。","cautions":["培养后水样可能含病原体。","BOD 瓶必须满瓶无气泡。"]},
"life-tea-ph":{"apparatus":["烧杯","试管","滴管","温度计"],"observation":"红茶加碱后明显变深，加酸后变浅。","conclusion":"茶汤颜色受 pH 与茶多酚氧化影响。","cautions":["热水烫伤风险。","碱性茶汤不可饮用。"]},
"life-honey-test":{"apparatus":["试管","滴管","酒精灯","天平"],"observation":"掺糖浆样品遇碘变蓝，燃烧有焦糖味。","conclusion":"简单测试可初筛掺假，但不能替代专业检测。","cautions":["燃烧少量，远离易燃物。","蜂蜜样品不可用于喂养婴儿。"]},
"life-fruit-ripening":{"apparatus":["密封袋","注射器","试管","计时器"],"observation":"与香蕉同袋的水果成熟更快。","conclusion":"乙烯促进果实成熟，可被氧化剂检验。","cautions":["密封袋不要完全缺氧。","高锰酸钾腐蚀，避免接触。"]},
"life-stain-removal":{"apparatus":["烧杯","温度计","刷子","天平"],"observation":"油渍需温水加洗涤剂，血渍冷水加酶效果最好，茶渍需氧化漂白。","conclusion":"污渍类型决定清洗条件，错误用热水会固定血渍。","cautions":["血渍布使用模拟液，避免生物污染。","酶制剂避免吸入。"]},
"life-egg-freshness":{"apparatus":["烧杯","量筒","手电筒","天平"],"observation":"越不新鲜的鸡蛋在越低浓度盐水中上浮，气室越大。","conclusion":"密度、气室与 pH 可综合判断鸡蛋新鲜度。","cautions":["生鸡蛋可能含沙门氏菌，操作后洗手。","破壳蛋不进入食品环节。"]},
"life-flour-gluten":{"apparatus":["烧杯","纱布","天平","烤箱"],"observation":"高筋面粉面筋多、弹性强。","conclusion":"面筋含量决定面粉适合做面包还是蛋糕。","cautions":["烤箱烘干时防烫伤。","生面粉不要食用。"]},
"life-oil-rancidity":{"apparatus":["锥形瓶","滴定管","水浴","试纸"],"observation":"反复加热油酸价明显升高，有哈喇味。","conclusion":"酸价可评价油脂酸败程度，煎炸油应定期更换。","cautions":["乙醚极易燃，严禁明火。","热油烫伤风险。"]},
"life-food-dye":{"apparatus":["层析纸","展开缸","毛细管","紫外灯"],"observation":"饮料中的色素分离成多个色斑。","conclusion":"纸层析可快速鉴别食品中的合成色素。","cautions":["展开剂易燃，通风处操作。","色素标准液避免入口。"]},
"nail-rust":{"apparatus":["试管 ×3","橡胶塞","标签纸","镊子"],"observation":"C 管的铁钉在水面附近先出现红褐色锈斑；A、B 管中的铁钉几天后仍光亮。","conclusion":"铁生锈需要同时接触氧气和水，两个条件缺一不可。","cautions":["使用干燥剂时避免吸入粉尘。","煮沸水时注意烫伤。","实验结束后铁钉与废液交实验员处理。"]},
"red-cabbage-indicator-lab":{"apparatus":["小锅或烧杯","纱布","点滴板或试管 ×5","滴管"],"observation":"加白醋变红，加蒸馏水基本不变，加小苏打与肥皂水变蓝绿色。","conclusion":"紫甘蓝汁可作酸碱指示剂，颜色随 pH 变化，适合做生活中的定性检测。","cautions":["加热时注意蒸汽烫伤。","不要品尝任何试液。","汁液易变质，当天用完。"]},
"starch-test":{"apparatus":["点滴板","滴管","镊子","小刀"],"observation":"米饭与土豆迅速变深蓝，苹果基本不变色，蒸馏水不变色。","conclusion":"碘液是检验淀粉的灵敏试剂，蓝色是碘与淀粉形成的包合物。","cautions":["碘液会染色衣物与皮肤，操作时小心。","样品刀具由教师统一管理。","实验后样品不要食用。"]},
"protein-salting-out":{"apparatus":["试管 ×4","试管夹","酒精灯","滴管"],"observation":"加盐后出现白色沉淀，稀释后重新变澄清；加热、加酸、加重金属盐都产生不再溶解的沉淀。","conclusion":"盐析可逆，变性不可逆；重金属盐使人中毒正是蛋白质变性的结果。","cautions":["加热试管时管口不要对人。","硫酸铜有毒，避免入口。","蛋清废液当日处理，不要久置发臭。"]},
"hard-water":{"apparatus":["试管 ×4","橡胶塞","滴管","量筒"],"observation":"蒸馏水很少几滴就起泡；自来水需要更多滴数；煮沸后滴数下降，经树脂处理后接近蒸馏水。","conclusion":"肥皂水可粗略判断硬度；煮沸只能除去暂时硬度，离子交换可较彻底地软化。","cautions":["肥皂水进入眼睛会刺激，注意防护。","煮沸后取样要冷却，避免烫伤。","树脂再生液按说明交实验员处理。"]},
"air-oxygen-content":{"apparatus":["集气瓶","燃烧匙","橡胶塞与导管","量筒","酒精灯"],"observation":"红磷燃烧产生大量白烟；冷却后水被吸入约容积的 1/5，剩余气体不能支持燃烧。","conclusion":"氧气约占空气体积的 1/5，剩余主要是氮气，化学性质较不活泼。","cautions":["红磷燃烧放热并产生白烟，在通风处进行并戴护目镜。","装置必须气密，否则结果偏小。","白烟有刺激性，尾气可经碱液吸收。"]},
"burning-conditions":{"apparatus":["铜片","大烧杯","薄铜片隔板","镊子","护目镜"],"observation":"铜片上的白磷很快燃烧并冒白烟，红磷不燃烧；水中的白磷也不燃烧。","conclusion":"水中白磷缺乏氧气、红磷温度不够，都不燃烧；只有三个条件同时满足才会燃烧。","cautions":["白磷剧毒且易自燃，只能由教师少量取用并现配现用。","必须戴护目镜，远离可燃物。","残余白磷交实验员按危险化学品处理。"]},
"catalyst-effect":{"apparatus":["锥形瓶 ×3","分液漏斗","导管","量筒或排水集气装置","秒表"],"observation":"加二氧化锰的一组迅速产生大量气泡，土豆组较慢，不加的一组几乎无现象。","conclusion":"催化剂加快反应速率而本身不被消耗；生物体内的酶也能催化过氧化氢分解。","cautions":["过氧化氢有腐蚀性，避免接触皮肤与眼睛。","加入固体后反应会放热，不要塞紧瓶口。","二氧化锰粉尘不要吸入。"]},
"temperature-rate":{"apparatus":["大烧杯（水浴）","试管 ×3","秒表","白纸与黑十字标记","温度计"],"observation":"温度越高，出现浑浊越快，遮住十字所需时间越短。","conclusion":"升高温度能显著加快反应速率，通常温度每升高 10 ℃，速率约增大到 2～4 倍。","cautions":["二氧化硫有刺激性，在通风处进行，量要小。","热水浴注意烫伤。","废液含硫与二氧化硫，交实验员处理。"]},
"glucose-reduction":{"apparatus":["试管 ×2","水浴锅","试管夹","滴管"],"observation":"斐林试剂由蓝色逐渐生成砖红色沉淀；银氨溶液组在管壁形成光亮的银镜。","conclusion":"葡萄糖含醛基，具有还原性，能把 Cu²⁺ 还原为 Cu₂O、把 Ag⁺ 还原为银。","cautions":["银氨溶液必须现配现用，久置会生成爆炸性的雷银。","实验后银镜用稀硝酸少量溶解，残液交实验员处理，不得久置。","水浴加热，不要用明火直接加热试管。"]}
};
